import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Injectable,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { DEPARTMENTS_KEY } from '../decorators/departments.decorator';

@Injectable()
export class DepartmentsGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredDepts = this.reflector.getAllAndOverride<string[]>(
      DEPARTMENTS_KEY,
      [context.getHandler(), context.getClass()],
    );

    if (!requiredDepts || requiredDepts.length === 0) {
      return true;
    }

    const { user } = context.switchToHttp().getRequest();
    if (!user || !requiredDepts.includes(user.department)) {
      throw new ForbiddenException('Insufficient department permissions');
    }

    return true;
  }
}

import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Injectable,
} from '@nestjs/common';

@Injectable()
export class ForcePasswordChangeGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest();
    const user = request.user;

    if (user?.forcePasswordChange) {
      const url = request.url;
      // Only allow access to change-password endpoint
      if (!url.includes('/auth/change-password')) {
        throw new ForbiddenException(
          'You must change your password before accessing any other resource',
        );
      }
    }

    return true;
  }
}

import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Injectable,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PERMISSIONS_KEY } from '../decorators/permissions.decorator';

@Injectable()
export class PermissionsGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredPermissions = this.reflector.getAllAndOverride<string[]>(
      PERMISSIONS_KEY,
      [context.getHandler(), context.getClass()],
    );

    if (!requiredPermissions || requiredPermissions.length === 0) {
      return true;
    }

    const { user } = context.switchToHttp().getRequest();
    if (!user || !user.permissions) {
      throw new ForbiddenException('Insufficient permissions');
    }

    const hasAllPermissions = requiredPermissions.every((perm) =>
      user.permissions.includes(perm),
    );

    if (!hasAllPermissions) {
      throw new ForbiddenException('Insufficient permissions');
    }

    return true;
  }
}

import {
  CanActivate,
  ExecutionContext,
  Injectable,
  HttpException,
  HttpStatus,
} from '@nestjs/common';
import { RedisService } from '../../infrastructure/cache/redis.client';

@Injectable()
export class RateLimitGuard implements CanActivate {
  private readonly defaultLimit = 100;
  private readonly defaultWindow = 60; // seconds

  constructor(private readonly redis: RedisService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    const ip = request.ip;
    const route = request.route?.path || request.url;

    // Special rate limits for auth endpoints
    let limit = this.defaultLimit;
    let window = this.defaultWindow;

    if (route.includes('/auth/login')) {
      limit = 5;
      window = 60;
    }

    const key = `ratelimit:${ip}:${route}`;
    const current = await this.redis.incr(key);

    if (current === 1) {
      // Set TTL on first request
      await this.redis.getClient().expire(key, window);
    }

    if (current > limit) {
      throw new HttpException(
        'Too many requests. Please try again later.',
        HttpStatus.TOO_MANY_REQUESTS,
      );
    }

    return true;
  }
}

import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Injectable,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY } from '../decorators/roles.decorator';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  private normalizeRoleName(role: unknown): string {
    return String(role ?? '')
      .toUpperCase()
      .trim();
  }

  private isAccountingFamilyRole(role: string): boolean {
    return role.includes('ACCOUNTING') || role.includes('MUHASEBE');
  }

  private hasRequiredRole(userRole: unknown, requiredRoles: string[]): boolean {
    const normalizedUserRole = this.normalizeRoleName(userRole);
    if (!normalizedUserRole) {
      return false;
    }

    return requiredRoles.some((requiredRole) => {
      const normalizedRequiredRole = this.normalizeRoleName(requiredRole);
      if (normalizedUserRole === normalizedRequiredRole) {
        return true;
      }

      // ACCOUNTING yetkisi verilen endpointlerde muhasebe alt rolleri de erisebilsin.
      if (normalizedRequiredRole === 'ACCOUNTING') {
        return this.isAccountingFamilyRole(normalizedUserRole);
      }

      return false;
    });
  }

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<string[]>(
      ROLES_KEY,
      [context.getHandler(), context.getClass()],
    );

    if (!requiredRoles || requiredRoles.length === 0) {
      return true;
    }

    const { user } = context.switchToHttp().getRequest();
    if (!user || !this.hasRequiredRole(user.role, requiredRoles)) {
      throw new ForbiddenException('Insufficient role permissions');
    }

    return true;
  }
}

export interface PaginationResult<T> {
  data: T[];
  meta: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  };
}

export function getPaginationParams(query: any): {
  page: number;
  limit: number;
  offset: number;
} {
  const page = Math.max(1, parseInt(query.page || '1', 10));
  const limit = Math.max(1, Math.min(100, parseInt(query.limit || '10', 10)));
  const offset = (page - 1) * limit;
  return { page, limit, offset };
}

export function createPaginationResult<T>(
  data: T[],
  total: number,
  page: number,
  limit: number,
): PaginationResult<T> {
  return {
    data,
    meta: {
      total,
      page,
      limit,
      totalPages: Math.ceil(total / limit),
    },
  };
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { Reflector } from '@nestjs/core';
import { WriteAuditLogUseCase } from '../../modules/audit/application/usecases/write-audit-log.usecase';

@Injectable()
export class AuditInterceptor implements NestInterceptor {
  constructor(
    private readonly reflector: Reflector,
    private readonly writeAuditLogUseCase: WriteAuditLogUseCase,
  ) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const req = context.switchToHttp().getRequest();
    const user = req.user;
    const method = req.method;
    const url = req.url;

    // Skip GET requests or if no user (public endpoints)
    if (method === 'GET' || !user) {
      return next.handle();
    }

    const ip = req.ip || req.connection.remoteAddress;
    const userAgent = req.headers['user-agent'];
    const resource =
      this.reflector.get<string>('resource', context.getHandler()) ||
      url.split('/')[1] ||
      'UNKNOWN';
    const action = method === 'DELETE' ? 'DELETE_IMPORTANT' : method;

    return next.handle().pipe(
      tap(async (data) => {
        // Log successful modification
        // If it's a POST/PUT/PATCH/DELETE
        try {
          const deletedItemLabel =
            method === 'DELETE' && data && typeof data === 'object'
              ? data.title ||
                data.name ||
                data.companyName ||
                data.email ||
                data.projectName ||
                data.description ||
                null
              : null;

          const deleteMetadata =
            method === 'DELETE'
              ? {
                  importance: 'HIGH',
                  auditTag: 'CRITICAL_DELETE',
                  requestPath: url,
                  deletedEntityId: req.params.id || (data && data.id) || null,
                  deletedItemLabel,
                  name: deletedItemLabel,
                  deletedData: data || null,
                }
              : null;

          await this.writeAuditLogUseCase.execute({
            userId: user.userId,
            action,
            resource: resource,
            resourceId: req.params.id || (data && data.id) || null,
            ipAddress: ip,
            userAgent: userAgent,
            // Store the request body (what the user sent) instead of the response data
            newData:
              method !== 'DELETE'
                ? req.body && Object.keys(req.body).length > 0
                  ? req.body
                  : data
                : deleteMetadata,
          });
        } catch (error) {
          console.error('Audit Log Error:', error);
          // Don't fail the request if audit logging fails
        }
      }),
    );
  }
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

export interface Response<T> {
  success: boolean;
  statusCode: number;
  data: T;
  timestamp: string;
  path: string;
  requestId: string;
}

@Injectable()
export class ResponseInterceptor<T> implements NestInterceptor<T, Response<T>> {
  intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Observable<Response<T>> {
    const ctx = context.switchToHttp();
    const response = ctx.getResponse();
    const request = ctx.getRequest();
    const statusCode = response.statusCode;

    return next.handle().pipe(
      map((data) => ({
        success: true,
        statusCode,
        data,
        timestamp: new Date().toISOString(),
        path: request.url,
        requestId: request.headers['x-request-id'],
      })),
    );
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  RequestTimeoutException,
} from '@nestjs/common';
import { Observable, throwError, TimeoutError } from 'rxjs';
import { catchError, timeout } from 'rxjs/operators';

@Injectable()
export class TimeoutInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    return next.handle().pipe(
      timeout(5000),
      catchError((err) => {
        if (err instanceof TimeoutError) {
          return throwError(() => new RequestTimeoutException());
        }
        return throwError(() => err);
      }),
    );
  }
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import * as xss from 'xss';

@Injectable()
export class XssInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const request = context.switchToHttp().getRequest();

    if (request.body && typeof request.body === 'object') {
      this.sanitizeObject(request.body);
    }
    if (request.query && typeof request.query === 'object') {
      this.sanitizeObject(request.query);
    }
    if (request.params && typeof request.params === 'object') {
      this.sanitizeObject(request.params);
    }

    return next.handle();
  }

  private sanitizeObject(obj: any): void {
    if (!obj || typeof obj !== 'object') {
      return;
    }

    Object.keys(obj).forEach((key) => {
      const value = obj[key];
      if (typeof value === 'string') {
        obj[key] = xss.filterXSS(value);
      } else if (typeof value === 'object' && value !== null) {
        this.sanitizeObject(value);
      }
    });
  }
}

import { Injectable, Logger, NestMiddleware } from '@nestjs/common';
import { NextFunction, Request, Response } from 'express';

@Injectable()
export class LoggerMiddleware implements NestMiddleware {
  private logger = new Logger('HTTP');

  use(req: Request, res: Response, next: NextFunction): void {
    const { ip, method, baseUrl } = req;
    const userAgent = req.get('user-agent') || '';
    const start = Date.now();

    res.on('finish', () => {
      const { statusCode } = res;
      const duration = Date.now() - start;
      const requestId = req.headers['x-request-id'];

      const message = `${method} ${baseUrl} ${statusCode} ${duration}ms - ${userAgent} ${ip} [${requestId}]`;

      if (process.env.NODE_ENV === 'production') {
        this.logger.log(
          JSON.stringify({
            method,
            url: baseUrl,
            statusCode,
            duration,
            userAgent,
            ip,
            requestId,
          }),
        );
      } else {
        this.logger.log(message);
      }
    });

    next();
  }
}

export class SanitizeUtil {
  static trim(obj: any): any {
    if (typeof obj === 'string') {
      return obj.trim();
    }
    if (typeof obj !== 'object' || obj === null) {
      return obj;
    }
    if (Array.isArray(obj)) {
      return obj.map((item) => SanitizeUtil.trim(item));
    }
    return Object.keys(obj).reduce((acc, key) => {
      acc[key] = SanitizeUtil.trim(obj[key]);
      return acc;
    }, {} as any);
  }
}

import {
  BadRequestException,
  ConflictException,
  InternalServerErrorException,
  UnprocessableEntityException,
} from '@nestjs/common';

export class PgErrorMapper {
  static map(error: any): void {
    if (!error.code) {
      throw error;
    }

    switch (error.code) {
      case '23505': // unique_violation
        throw new ConflictException('Resource already exists');
      case '23503': // foreign_key_violation
        throw new UnprocessableEntityException('Referenced resource not found');
      case '23502': // not_null_violation
        throw new BadRequestException('Missing required fields');
      case '23514': // check_violation
        throw new UnprocessableEntityException('Validation check failed');
      case '57014': // query_canceled
        throw new InternalServerErrorException('Query timeout');
      default:
        throw error;
    }
  }
}

import {
  Inject,
  Injectable,
  Logger,
  OnModuleDestroy,
  OnModuleInit,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { Pool } from 'pg';
import databaseConfig from '../config/database.config';

@Injectable()
export class DatabasePool implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(DatabasePool.name);
  private pool: Pool;

  constructor(
    @Inject(databaseConfig.KEY)
    private readonly dbConfig: ConfigType<typeof databaseConfig>,
  ) {
    this.pool = new Pool({
      host: this.dbConfig.host,
      port: this.dbConfig.port,
      user: this.dbConfig.user,
      password: this.dbConfig.password,
      database: this.dbConfig.name,
      max: this.dbConfig.maxConnections,
      min: this.dbConfig.minConnections,
      ssl: this.dbConfig.ssl ? { rejectUnauthorized: false } : undefined,
    });
  }

  async onModuleInit() {
    try {
      const client = await this.pool.connect();
      this.logger.log('Database connection established successfully');
      client.release();
    } catch (error) {
      this.logger.error('Failed to connect to the database', error.stack);
      throw error;
    }
  }

  async onModuleDestroy() {
    await this.pool.end();
    this.logger.log('Database connection pool closed');
  }

  getPool(): Pool {
    return this.pool;
  }
}

import { DatabasePool } from '../pool';
import { Logger } from '@nestjs/common';

export abstract class BaseRepository<T> {
  protected readonly logger: Logger;

  constructor(
    protected readonly pool: DatabasePool,
    protected readonly tableName: string,
  ) {
    this.logger = new Logger(this.constructor.name);
  }

  protected async query<R = any>(text: string, params?: any[]): Promise<R[]> {
    const client = await this.pool.getPool().connect();
    try {
      const result = await client.query(text, params);
      return result.rows;
    } finally {
      client.release();
    }
  }

  protected async queryOne<R = any>(
    text: string,
    params?: any[],
  ): Promise<R | null> {
    const rows = await this.query<R>(text, params);
    return rows.length > 0 ? rows[0] : null;
  }

  async findAll(): Promise<T[]> {
    return this.query<T>(`SELECT * FROM ${this.tableName}`);
  }

  async findById(id: string): Promise<T | null> {
    return this.queryOne<T>(`SELECT * FROM ${this.tableName} WHERE id = $1`, [
      id,
    ]);
  }

  async delete(id: string): Promise<boolean> {
    const result = await this.query(
      `DELETE FROM ${this.tableName} WHERE id = $1 RETURNING id`,
      [id],
    );
    return result.length > 0;
  }
}

