import { Injectable, Inject, Logger } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigType } from '@nestjs/config';
import * as crypto from 'crypto';
import jwtConfig from '../../../../config/jwt.config';
import { UsersRepository } from '../../../users/infrastructure/users.repository';
import { PasswordService } from '../password.service';
import { RefreshTokenRepository } from '../../infrastructure/refresh-token.repository';
import {
  InvalidCredentialsException,
  AccountDeactivatedException,
} from '../../domain/auth.errors';

@Injectable()
export class LoginUseCase {
  private readonly logger = new Logger(LoginUseCase.name);

  constructor(
    private readonly usersRepo: UsersRepository,
    private readonly passwordService: PasswordService,
    private readonly refreshTokenRepo: RefreshTokenRepository,
    private readonly jwtService: JwtService,
    @Inject(jwtConfig.KEY)
    private readonly jwtConf: ConfigType<typeof jwtConfig>,
  ) {}

  async execute(email: string, password: string) {
    // 1. Find user
    const user = await this.usersRepo.findByEmail(email);
    if (!user) {
      throw new InvalidCredentialsException();
    }

    if (!user.is_active) {
      throw new AccountDeactivatedException();
    }

    // 2. Verify password
    const isPasswordValid = await this.passwordService.compare(
      password,
      user.password_hash,
    );
    if (!isPasswordValid) {
      throw new InvalidCredentialsException();
    }

    // 3. Generate tokens
    const tokens = await this.generateTokens(user);

    // 4. Store refresh token
    const tokenHash = this.hashToken(tokens.refreshToken);
    const refreshExpMs = this.parseExpiration(this.jwtConf.refreshExpiration);
    const expiresAt = new Date(Date.now() + refreshExpMs);
    await this.refreshTokenRepo.create(user.id, tokenHash, expiresAt);

    this.logger.log(`User ${user.email} logged in successfully`);

    return {
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      user: {
        id: user.id,
        email: user.email,
        firstName: user.first_name,
        lastName: user.last_name,
        role: user.role,
        department: user.department,
        avatarUrl: user.avatar_url ?? null,
        avatarFit: user.avatar_fit ?? null,
        avatarPosition: user.avatar_position ?? null,
        forcePasswordChange: user.force_password_change,
      },
    };
  }

  private async generateTokens(user: any) {
    const firstName = (user.first_name ?? user.firstName ?? '').trim();
    const lastName = (user.last_name ?? user.lastName ?? '').trim();
    const name = `${firstName} ${lastName}`.trim();

    const payload = {
      sub: user.id,
      email: user.email,
      role: user.role,
      department: user.department,
      firstName,
      lastName,
      name: name || user.email,
    };

    const [accessToken, refreshToken] = await Promise.all([
      this.jwtService.signAsync(payload, {
        secret: this.jwtConf.accessSecret,
        expiresIn: this.jwtConf.accessExpiration as any,
      }),
      this.jwtService.signAsync(payload, {
        secret: this.jwtConf.refreshSecret,
        expiresIn: this.jwtConf.refreshExpiration as any,
      }),
    ]);

    return { accessToken, refreshToken };
  }

  private hashToken(token: string): string {
    return crypto.createHash('sha256').update(token).digest('hex');
  }

  private parseExpiration(expiration: string): number {
    const match = expiration.match(/^(\d+)([smhd])$/);
    if (!match) return 7 * 24 * 60 * 60 * 1000; // default 7 days

    const value = parseInt(match[1]);
    const unit = match[2];
    const multipliers: Record<string, number> = {
      s: 1000,
      m: 60 * 1000,
      h: 60 * 60 * 1000,
      d: 24 * 60 * 60 * 1000,
    };
    return value * (multipliers[unit] || 1000);
  }
}

import { Injectable, Inject, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigType } from '@nestjs/config';
import * as crypto from 'crypto';
import jwtConfig from '../../../../config/jwt.config';
import { RefreshTokenRepository } from '../../infrastructure/refresh-token.repository';
import { UsersRepository } from '../../../users/infrastructure/users.repository';

@Injectable()
export class RefreshTokenUseCase {
  constructor(
    private readonly jwtService: JwtService,
    private readonly refreshTokenRepo: RefreshTokenRepository,
    private readonly usersRepo: UsersRepository,
    @Inject(jwtConfig.KEY)
    private readonly jwtConf: ConfigType<typeof jwtConfig>,
  ) {}

  async execute(refreshToken: string) {
    try {
      const decoded = await this.jwtService.verifyAsync(refreshToken, {
        secret: this.jwtConf.refreshSecret,
      });

      const tokenHash = this.hashToken(refreshToken);
      const isStored = await this.refreshTokenRepo.findByTokenHash(tokenHash);

      if (!isStored || isStored.user_id !== decoded.sub) {
        throw new UnauthorizedException(
          'Refresh token is invalid or does not belong to user',
        );
      }

      const user = await this.usersRepo.findById(decoded.sub);
      if (
        !user ||
        ((!user as any).isActive &&
          user.isActive === false &&
          (user as any).is_active === false)
      ) {
        throw new UnauthorizedException('User is inactive or not found');
      }

      // Format correct payload exactly like login
      const firstName = (
        ((user as any).first_name as string | undefined) ??
        user.firstName ??
        ''
      ).trim();
      const lastName = (
        ((user as any).last_name as string | undefined) ??
        user.lastName ??
        ''
      ).trim();
      const name = `${firstName} ${lastName}`.trim();
      const payload = {
        sub: user.id,
        email: user.email,
        role: user.role,
        department: user.department,
        firstName,
        lastName,
        name: name || user.email,
      };

      const [newAccessToken, newRefreshToken] = await Promise.all([
        this.jwtService.signAsync(payload, {
          secret: this.jwtConf.accessSecret,
          expiresIn: this.jwtConf.accessExpiration as any,
        }),
        this.jwtService.signAsync(payload, {
          secret: this.jwtConf.refreshSecret,
          expiresIn: this.jwtConf.refreshExpiration as any,
        }),
      ]);

      // Revoke old refresh token, store new one
      await this.refreshTokenRepo.revokeByTokenHash(tokenHash);

      const newHash = this.hashToken(newRefreshToken);
      const refreshExpMs = this.parseExpiration(this.jwtConf.refreshExpiration);
      const expiresAt = new Date(Date.now() + refreshExpMs);
      await this.refreshTokenRepo.create(user.id, newHash, expiresAt);

      return {
        accessToken: newAccessToken,
        refreshToken: newRefreshToken,
      };
    } catch (e) {
      if (e instanceof UnauthorizedException) {
        throw e;
      }
      throw new UnauthorizedException('Invalid refresh token');
    }
  }

  private hashToken(token: string): string {
    return crypto.createHash('sha256').update(token).digest('hex');
  }

  private parseExpiration(expiration: string): number {
    const match = expiration.match(/^(\d+)([smhd])$/);
    if (!match) return 7 * 24 * 60 * 60 * 1000;
    const value = parseInt(match[1]);
    const unit = match[2];
    const multipliers: Record<string, number> = {
      s: 1000,
      m: 60 * 1000,
      h: 60 * 60 * 1000,
      d: 24 * 60 * 60 * 1000,
    };
    return value * (multipliers[unit] || 1000);
  }
}

import { Injectable, Inject } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigType } from '@nestjs/config';
import * as crypto from 'crypto';
import jwtConfig from '../../../../config/jwt.config';
import { UsersRepository } from '../../../users/infrastructure/users.repository';
import { RefreshTokenRepository } from '../../infrastructure/refresh-token.repository';
import {
  TokenRevokedException,
  TokenExpiredException,
  AccountDeactivatedException,
} from '../../domain/auth.errors';

@Injectable()
export class RefreshUseCase {
  constructor(
    private readonly usersRepo: UsersRepository,
    private readonly refreshTokenRepo: RefreshTokenRepository,
    private readonly jwtService: JwtService,
    @Inject(jwtConfig.KEY)
    private readonly jwtConf: ConfigType<typeof jwtConfig>,
  ) {}

  async execute(refreshToken: string) {
    // 1. Hash the token and find in DB
    const tokenHash = this.hashToken(refreshToken);
    const storedToken = await this.refreshTokenRepo.findByTokenHash(tokenHash);

    if (!storedToken) {
      throw new TokenRevokedException();
    }

    if (new Date(storedToken.expires_at) < new Date()) {
      throw new TokenExpiredException();
    }

    // 2. Revoke old token (rotation)
    await this.refreshTokenRepo.revokeByTokenHash(tokenHash);

    // 3. Get user
    const user = await this.usersRepo.findById(storedToken.user_id);

    if (!user || !user.isActive) {
      throw new AccountDeactivatedException();
    }

    // 4. Generate new token pair
    const tokens = await this.generateTokens(user);

    // 5. Store new refresh token
    const newTokenHash = this.hashToken(tokens.refreshToken);
    const refreshExpMs = this.parseExpiration(this.jwtConf.refreshExpiration);
    const expiresAt = new Date(Date.now() + refreshExpMs);
    await this.refreshTokenRepo.create(user.id, newTokenHash, expiresAt);

    return {
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
    };
  }

  private async generateTokens(user: any) {
    const firstName = (user.first_name ?? user.firstName ?? '').trim();
    const lastName = (user.last_name ?? user.lastName ?? '').trim();
    const name = `${firstName} ${lastName}`.trim();

    const payload = {
      sub: user.id,
      email: user.email,
      role: user.role,
      department: user.department,
      firstName,
      lastName,
      name: name || user.email,
    };

    const [accessToken, refreshToken] = await Promise.all([
      this.jwtService.signAsync(payload, {
        secret: this.jwtConf.accessSecret,
        expiresIn: this.jwtConf.accessExpiration as any,
      }),
      this.jwtService.signAsync(payload, {
        secret: this.jwtConf.refreshSecret,
        expiresIn: this.jwtConf.refreshExpiration as any,
      }),
    ]);

    return { accessToken, refreshToken };
  }

  private hashToken(token: string): string {
    return crypto.createHash('sha256').update(token).digest('hex');
  }

  private parseExpiration(expiration: string): number {
    const match = expiration.match(/^(\d+)([smhd])$/);
    if (!match) return 7 * 24 * 60 * 60 * 1000; // default 7 days

    const value = parseInt(match[1]);
    const unit = match[2];
    const multipliers: Record<string, number> = {
      s: 1000,
      m: 60 * 1000,
      h: 60 * 60 * 1000,
      d: 24 * 60 * 60 * 1000,
    };
    return value * (multipliers[unit] || 1000);
  }
}

import { Test, TestingModule } from '@nestjs/testing';
