        'Ilk giriste sifrenizi degistirmeniz gerekiyor. Lutfen once sifre guncelleyin.',
      );
    }

    const clientId = req.user.clientId || req.user.userId;
    return this.clientsPublicService.createClientPortalRequest(
      clientId,
      req.user.userId,
      dto,
    );
  }
}

