import { Injectable, UnauthorizedException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import { Role } from '../../../../shared/enums/role.enum';
import { ClientsRepository } from '../../infrastructure/clients.repository';
import { ClientUsersRepository } from '../../infrastructure/client-users.repository';

@Injectable()
export class ClientPortalLoginUseCase {
  constructor(
    private readonly clientUsersRepo: ClientUsersRepository,
    private readonly clientsRepo: ClientsRepository,
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
  ) {}

  async execute(email: string, password: string) {
    const clientUser = await this.clientUsersRepo.findByEmail(email);
    if (!clientUser) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const isPasswordValid = await bcrypt.compare(
      password,
      clientUser.passwordHash,
    );
    if (!isPasswordValid) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const client = await this.clientsRepo.findById(clientUser.clientId);
    if (!client || !client.isActive) {
      throw new UnauthorizedException('Client account is inactive');
    }

    const accessSecret = this.configService.get<string>('jwt.accessSecret');
    const refreshSecret = this.configService.get<string>('jwt.refreshSecret');
    const accessExpiration =
      this.configService.get<string>('jwt.accessExpiration') || '15m';
    const refreshExpiration =
      this.configService.get<string>('jwt.refreshExpiration') || '7d';

    const contactPerson = (client.contactPerson || '').trim();
    const [firstName = '', ...rest] = contactPerson
      .split(/\s+/)
      .filter(Boolean);
    const lastName = rest.join(' ');

    const payload = {
      sub: clientUser.id,
      email: clientUser.email,
      role: Role.CLIENT,
      department: 'CLIENT',
      clientId: client.id,
      forcePasswordChange: Boolean(clientUser.forcePasswordChange),
      firstName,
      lastName,
      name: contactPerson || client.companyName,
    };

    const [accessToken, refreshToken] = await Promise.all([
      this.jwtService.signAsync(payload, {
        secret: accessSecret,
        expiresIn: accessExpiration as any,
      }),
      this.jwtService.signAsync(payload, {
        secret: refreshSecret,
        expiresIn: refreshExpiration as any,
      }),
    ]);

    return {
      accessToken,
      refreshToken,
      user: {
        id: clientUser.id,
        email: clientUser.email,
        firstName,
        lastName,
        role: Role.CLIENT,
        department: 'CLIENT',
        forcePasswordChange: Boolean(clientUser.forcePasswordChange),
        clientId: client.id,
      },
    };
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { CreateClientUseCase } from './create-client.usecase';
import { ClientsRepository } from '../../infrastructure/clients.repository';
import { ClientAlreadyExistsException } from '../../application/clients.service';

describe('CreateClientUseCase', () => {
  let useCase: CreateClientUseCase;
  let clientsRepo: Partial<jest.Mocked<ClientsRepository>>;

  const mockDto: any = {
    companyName: 'Acme Corp',
    contactPerson: 'John Doe',
    email: 'john@acme.com',
    phone: '+905551234567',
    address: 'Istanbul, Turkey',
  };

  const mockCreatedClient: any = {
    id: 'client-1',
    companyName: 'Acme Corp',
    contactPerson: 'John Doe',
    email: 'john@acme.com',
    phone: '+905551234567',
    address: 'Istanbul, Turkey',
    isActive: true,
    createdAt: new Date(),
    updatedAt: new Date(),
  };

  beforeEach(async () => {
    clientsRepo = {
      findByEmail: jest.fn(),
      findByCompanyName: jest.fn(),
      create: jest.fn(),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        CreateClientUseCase,
        { provide: ClientsRepository, useValue: clientsRepo },
      ],
    }).compile();

    useCase = module.get<CreateClientUseCase>(CreateClientUseCase);
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('should be defined', () => {
    expect(useCase).toBeDefined();
  });

  describe('execute', () => {
    it('should create client successfully when email and company name are unique', async () => {
      clientsRepo.findByEmail.mockResolvedValue(null);
      clientsRepo.findByCompanyName.mockResolvedValue(null);
      clientsRepo.create.mockResolvedValue(mockCreatedClient);

      const result = await useCase.execute(mockDto);

      expect(result).toEqual(mockCreatedClient);
      expect(clientsRepo.findByEmail).toHaveBeenCalledWith('john@acme.com');
      expect(clientsRepo.findByCompanyName).toHaveBeenCalledWith('Acme Corp');
      expect(clientsRepo.create).toHaveBeenCalledWith({
        companyName: 'Acme Corp',
        contactPerson: 'John Doe',
        email: 'john@acme.com',
        phone: '+905551234567',
        address: 'Istanbul, Turkey',
      });
    });

    it('should throw ClientAlreadyExistsException when email already exists', async () => {
      clientsRepo.findByEmail.mockResolvedValue(mockCreatedClient);

      await expect(useCase.execute(mockDto)).rejects.toThrow(
        ClientAlreadyExistsException,
      );

      expect(clientsRepo.findByEmail).toHaveBeenCalledWith('john@acme.com');
      expect(clientsRepo.create).not.toHaveBeenCalled();
    });

    it('should throw ClientAlreadyExistsException when company name already exists', async () => {
      clientsRepo.findByEmail.mockResolvedValue(null);
      clientsRepo.findByCompanyName.mockResolvedValue(mockCreatedClient);

      await expect(useCase.execute(mockDto)).rejects.toThrow(
        ClientAlreadyExistsException,
      );

      expect(clientsRepo.findByCompanyName).toHaveBeenCalledWith('Acme Corp');
      expect(clientsRepo.create).not.toHaveBeenCalled();
    });

    it('should create client without optional fields', async () => {
      const minimalDto: any = {
        companyName: 'Minimal Corp',
        contactPerson: 'Jane',
        email: 'jane@minimal.com',
      };

      clientsRepo.findByEmail.mockResolvedValue(null);
      clientsRepo.findByCompanyName.mockResolvedValue(null);
      clientsRepo.create.mockResolvedValue({
        id: 'client-2',
        ...minimalDto,
      });

      const result = await useCase.execute(minimalDto);

      expect(result.id).toBe('client-2');
      expect(clientsRepo.create).toHaveBeenCalledWith(
        expect.objectContaining({
          companyName: 'Minimal Corp',
          contactPerson: 'Jane',
          email: 'jane@minimal.com',
        }),
      );
    });
  });
});

import { Injectable, BadRequestException, Logger } from '@nestjs/common';
import { ClientUsersRepository } from '../../infrastructure/client-users.repository';
import { ForceChangeClientPasswordDto } from '../../api/dto/force-change-client-password.dto';
import * as bcrypt from 'bcrypt';

@Injectable()
export class ForceChangeClientPasswordUseCase {
  private readonly logger = new Logger(ForceChangeClientPasswordUseCase.name);

  constructor(private readonly clientUsersRepo: ClientUsersRepository) {}

  async execute(dto: ForceChangeClientPasswordDto) {
    // İstemci id doğrulama için öncelikle DB dökümü alınmalı (Eğer id ile bulma yazıldıysa)
    // Repo'da sadece 'findByEmail' olduğu için şu aşamada DB seviyesinde Update işlemi NotFound dönebilir.
    // İleriki fazlarda "findById" eklendiğinde tam kullanıcı kontrolü sağlanabilir.

    try {
      // Şifreyi bcrypt ile tuzla (hash)
      const saltRounds = 10;
      const hashedPassword = await bcrypt.hash(dto.newPassword, saltRounds);

      // Veritabanını güncelle
      await this.clientUsersRepo.updatePasswordHash(
        dto.clientId,
        hashedPassword,
      );

      this.logger.log(
        `Client user password forcefully changed. ClientID: ${dto.clientId}`,
      );

      return {
        success: true,
        message:
          'İstemci şifresi başarıyla güncellendi. Yeni şifreyle sisteme giriş yapılabilir.',
      };
    } catch (error) {
      this.logger.error(`Error updating client password: ${error.message}`);
      // Örneğin: clientId geçersiz bir uuid ise db fırlatır
      throw new BadRequestException(
        'Şifre güncellenirken bir hata oluştu veya geçersiz Master Müşteri ID.',
      );
    }
  }
}

