export enum FileEntityType {
  CONTRACT = 'CONTRACT',
  INVOICE = 'INVOICE',
  PROJECT = 'PROJECT',
  TICKET = 'TICKET',
  EXPENSE = 'EXPENSE',
}

export interface FileEntity {
