  fileName: string;
  filePath: string;
  mimeType?: string;
  size?: number;
  entityType?: FileEntityType;
  entityId?: string;
  uploadedBy?: string;
  createdAt: Date;
}

export class FileRecord implements FileEntity {
  id: string;
  fileName: string;
  filePath: string;
  mimeType?: string;
  size?: number;
  entityType?: FileEntityType;
  entityId?: string;
  uploadedBy?: string;
  createdAt: Date;

  static fromRow(row: any): FileRecord {
