import { Injectable } from '@nestjs/common';
import { PoolClient } from 'pg';
import { DatabasePool } from '../../../../database/pool';
import { BaseQuery } from '../../../../database/query/base-query';
import { InvoiceQueryDto } from '../api/dto/invoice-query.dto';
import {
  Invoice,
  InvoiceEntity,
  InvoiceItemEntity,
} from '../domain/invoice.entity';
import { InvoicesSql } from './sql/invoices.sql';

interface InvoiceSchemaSnapshot {
  hasInvoiceNumber: boolean;
  hasProjectId: boolean;
  hasSubtotal: boolean;
  hasTaxRate: boolean;
  hasTaxAmount: boolean;
  hasTotal: boolean;
  hasIssueDate: boolean;
  hasNotes: boolean;
  hasCreatedBy: boolean;
  hasTotalAmount: boolean;
  hasPaidAmount: boolean;
  hasUpdatedAt: boolean;
}

interface InvoiceItemSchemaSnapshot {
  hasQuantity: boolean;
  hasUnitPrice: boolean;
  hasTotal: boolean;
  hasAmount: boolean;
}

@Injectable()
export class InvoicesRepository {
  private invoiceSchemaCache: InvoiceSchemaSnapshot | null = null;
  private invoiceItemSchemaCache: InvoiceItemSchemaSnapshot | null = null;

  constructor(private readonly db: DatabasePool) {}

  async create(
    invoiceData: Partial<InvoiceEntity>,
    items: any[],
    client: PoolClient,
  ): Promise<InvoiceEntity> {
    const invoiceSchema = await this.getInvoiceSchema(client);
    const itemSchema = await this.getInvoiceItemSchema(client);
    const canUseModernInsert =
      invoiceSchema.hasInvoiceNumber &&
      invoiceSchema.hasProjectId &&
      invoiceSchema.hasSubtotal &&
      invoiceSchema.hasTaxRate &&
      invoiceSchema.hasTaxAmount &&
      invoiceSchema.hasTotal &&
      invoiceSchema.hasIssueDate &&
      invoiceSchema.hasNotes &&
      invoiceSchema.hasCreatedBy;

    const invoiceRow = canUseModernInsert
      ? await BaseQuery.queryOne<any>(client, InvoicesSql.insertInvoice, [
          invoiceData.invoiceNumber,
          invoiceData.clientId,
          invoiceData.projectId ?? null,
          invoiceData.status,
          invoiceData.subtotal,
          invoiceData.taxRate,
          invoiceData.taxAmount,
          invoiceData.total,
          invoiceData.issueDate,
          invoiceData.dueDate,
          invoiceData.notes,
          invoiceData.createdBy,
        ])
      : await this.insertInvoiceWithSchemaCompatibility(
          client,
          invoiceSchema,
          invoiceData,
        );

    const invoice = Invoice.fromRow(invoiceRow);

    if (items.length > 0) {
      const createdItems: InvoiceItemEntity[] = [];
      for (const item of items) {
        const itemTotal = item.quantity * item.unitPrice;
        const itemRow =
          itemSchema.hasQuantity &&
          itemSchema.hasUnitPrice &&
          itemSchema.hasTotal
            ? await BaseQuery.queryOne<any>(
                client,
                InvoicesSql.insertInvoiceItem,
                [
                  invoice.id,
                  item.description,
                  item.quantity,
                  item.unitPrice,
                  itemTotal,
                ],
              )
            : await BaseQuery.queryOne<any>(
                client,
                `
                  INSERT INTO invoice_items (invoice_id, description, amount)
                  VALUES ($1, $2, $3)
                  RETURNING *
                `,
                [invoice.id, item.description, itemTotal],
              );
        createdItems.push(Invoice.itemFromRow(itemRow));
      }
      invoice.items = createdItems;
    }

    return invoice;
  }

  async findAll(query: InvoiceQueryDto): Promise<InvoiceEntity[]> {
    const client = await this.db.getPool().connect();
    try {
      const invoiceSchema = await this.getInvoiceSchema(client);
      let sql = invoiceSchema.hasProjectId
        ? InvoicesSql.findAll
        : `
            SELECT i.*,
                   c.company_name as client_name,
                   NULL::text as project_name
            FROM invoices i
            LEFT JOIN clients c ON i.client_id = c.id
            WHERE 1=1
          `;
      const params: any[] = [];
      let pIdx = 1;

      if (query.status) {
        sql += ` AND i.status = $${pIdx++}`;
        params.push(query.status);
      }
      if (query.clientId) {
        sql += ` AND i.client_id = $${pIdx++}`;
        params.push(query.clientId);
      }
      if (query.projectId && invoiceSchema.hasProjectId) {
        sql += ` AND i.project_id = $${pIdx++}`;
        params.push(query.projectId);
      }
      // Pagination
      const limit = query.limit || 10;
      const offset = ((query.page || 1) - 1) * limit;
      sql += ` ORDER BY i.created_at DESC LIMIT $${pIdx++} OFFSET $${pIdx++}`;
      params.push(limit, offset);

      const rows = await BaseQuery.queryMany<any>(client, sql, params);
      return rows.map((row) => Invoice.fromRow(row));
    } finally {
      client.release();
    }
  }

  async findById(
    id: string,
    client?: PoolClient,
  ): Promise<InvoiceEntity | null> {
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const invoiceSchema = await this.getInvoiceSchema(dbClient);
      const row = invoiceSchema.hasProjectId
        ? await BaseQuery.queryOne<any>(dbClient, InvoicesSql.findById, [id])
        : await BaseQuery.queryOne<any>(
            dbClient,
            `
              SELECT i.*,
                     c.company_name as client_name,
                     NULL::text as project_name
              FROM invoices i
              LEFT JOIN clients c ON i.client_id = c.id
              WHERE i.id = $1
            `,
            [id],
          );
      if (!row) return null;

      const invoice = Invoice.fromRow(row);

      // Fetch items
      const itemRows = await BaseQuery.queryMany<any>(
        dbClient,
        InvoicesSql.findItemsByInvoiceId,
        [id],
      );
      invoice.items = itemRows.map((row) => Invoice.itemFromRow(row));

      return invoice;
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async updateStatus(
    id: string,
    status: string,
    client?: PoolClient,
  ): Promise<InvoiceEntity | null> {
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;

    try {
      const row = await BaseQuery.queryOne<any>(
        dbClient,
        InvoicesSql.updateStatus,
        [status, id],
      );
      return row ? Invoice.fromRow(row) : null;
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async countInvoicesByYear(year: number): Promise<number> {
    const client = await this.db.getPool().connect();
    try {
      const row = await BaseQuery.queryOne<any>(
        client,
        InvoicesSql.countByYear,
        [year],
      );
      return parseInt(row.count, 10);
    } finally {
      client.release();
    }
  }

  async sumByDateRange(
    startDate: Date,
    endDate: Date,
  ): Promise<{ totalIssued: number; totalCollected: number }> {
    const client = await this.db.getPool().connect();
    try {
      const invoiceSchema = await this.getInvoiceSchema(client);
      const row = invoiceSchema.hasSubtotal
        ? await BaseQuery.queryOne<any>(client, InvoicesSql.sumByDateRange, [
            startDate,
            endDate,
          ])
        : await BaseQuery.queryOne<any>(
            client,
            `
              SELECT
                COALESCE(SUM(total_amount), 0) as total_issued,
                COALESCE(SUM(paid_amount), 0) as total_collected
              FROM invoices
              WHERE created_at >= $1 AND created_at <= $2
            `,
            [startDate, endDate],
          );
      return {
        totalIssued: parseFloat(row?.total_issued || '0'),
        totalCollected: parseFloat(row?.total_collected || '0'),
      };
    } finally {
      client.release();
    }
  }

  private async getInvoiceSchema(
    client: PoolClient,
  ): Promise<InvoiceSchemaSnapshot> {
    if (this.invoiceSchemaCache) {
      return this.invoiceSchemaCache;
    }

    try {
      const rows = await BaseQuery.queryMany<{ column_name: string }>(
        client,
        `
          SELECT column_name
          FROM information_schema.columns
          WHERE table_schema = 'public' AND table_name = 'invoices'
        `,
        [],
      );
      const columns = new Set((rows || []).map((row) => row.column_name));

      this.invoiceSchemaCache = {
        hasInvoiceNumber: columns.has('invoice_number'),
        hasProjectId: columns.has('project_id'),
        hasSubtotal: columns.has('subtotal'),
        hasTaxRate: columns.has('tax_rate'),
        hasTaxAmount: columns.has('tax_amount'),
        hasTotal: columns.has('total'),
        hasIssueDate: columns.has('issue_date'),
        hasNotes: columns.has('notes'),
        hasCreatedBy: columns.has('created_by'),
        hasTotalAmount: columns.has('total_amount'),
        hasPaidAmount: columns.has('paid_amount'),
        hasUpdatedAt: columns.has('updated_at'),
      };
    } catch {
      // Keep old behavior if schema inspection is not available in tests/runtime.
      this.invoiceSchemaCache = {
        hasInvoiceNumber: true,
        hasProjectId: true,
        hasSubtotal: true,
        hasTaxRate: true,
        hasTaxAmount: true,
        hasTotal: true,
        hasIssueDate: true,
        hasNotes: true,
        hasCreatedBy: true,
        hasTotalAmount: true,
        hasPaidAmount: true,
        hasUpdatedAt: true,
      };
    }

    return this.invoiceSchemaCache;
  }

  private async getInvoiceItemSchema(
    client: PoolClient,
  ): Promise<InvoiceItemSchemaSnapshot> {
    if (this.invoiceItemSchemaCache) {
      return this.invoiceItemSchemaCache;
    }

    try {
      const rows = await BaseQuery.queryMany<{ column_name: string }>(
        client,
        `
          SELECT column_name
          FROM information_schema.columns
          WHERE table_schema = 'public' AND table_name = 'invoice_items'
        `,
        [],
      );
      const columns = new Set((rows || []).map((row) => row.column_name));

      this.invoiceItemSchemaCache = {
        hasQuantity: columns.has('quantity'),
        hasUnitPrice: columns.has('unit_price'),
        hasTotal: columns.has('total'),
        hasAmount: columns.has('amount'),
      };
    } catch {
      this.invoiceItemSchemaCache = {
        hasQuantity: true,
        hasUnitPrice: true,
        hasTotal: true,
        hasAmount: false,
      };
    }

    return this.invoiceItemSchemaCache;
  }

  private async insertInvoiceWithSchemaCompatibility(
    client: PoolClient,
    schema: InvoiceSchemaSnapshot,
    invoiceData: Partial<InvoiceEntity>,
  ): Promise<any> {
    const columns: string[] = ['client_id'];
    const values: any[] = [invoiceData.clientId];

    if (schema.hasInvoiceNumber) {
      columns.push('invoice_number');
      values.push(
        invoiceData.invoiceNumber ||
          `INV-${Date.now().toString().slice(-6)}-${Math.floor(
            Math.random() * 1000,
          )
            .toString()
            .padStart(3, '0')}`,
      );
    }
    if (schema.hasProjectId) {
      columns.push('project_id');
      values.push(invoiceData.projectId ?? null);
    }
    if (schema.hasSubtotal) {
      columns.push('subtotal');
      values.push(invoiceData.subtotal ?? invoiceData.total ?? 0);
    }
    if (schema.hasTaxRate) {
      columns.push('tax_rate');
      values.push(invoiceData.taxRate ?? 0);
    }
    if (schema.hasTaxAmount) {
      columns.push('tax_amount');
      values.push(invoiceData.taxAmount ?? 0);
    }
    if (schema.hasTotal) {
      columns.push('total');
      values.push(invoiceData.total ?? 0);
    }
    if (schema.hasTotalAmount) {
      columns.push('total_amount');
      values.push(invoiceData.total ?? 0);
    }
    if (schema.hasPaidAmount) {
      columns.push('paid_amount');
      values.push(0);
    }

    columns.push('status');
    values.push(invoiceData.status || 'DRAFT');

    if (schema.hasIssueDate) {
      columns.push('issue_date');
      values.push(invoiceData.issueDate || new Date());
    }

    columns.push('due_date');
    values.push(invoiceData.dueDate || null);

    if (schema.hasNotes) {
      columns.push('notes');
      values.push(invoiceData.notes ?? null);
    }
    if (schema.hasCreatedBy) {
      columns.push('created_by');
      values.push(invoiceData.createdBy ?? null);
    }

    columns.push('created_at');

    const placeholders = values.map((_, index) => `$${index + 1}`);
    placeholders.push('NOW()');

    const sql = `
      INSERT INTO invoices (${columns.join(', ')})
      VALUES (${placeholders.join(', ')})
      RETURNING *
    `;

    return BaseQuery.queryOne<any>(client, sql, values);
  }
}

export enum AccountType {
  ASSET = 'ASSET',
  LIABILITY = 'LIABILITY',
  EQUITY = 'EQUITY',
  REVENUE = 'REVENUE',
  EXPENSE = 'EXPENSE',
}

export enum AccountCode {
  // Assets
  CASH = '100',
  BANK = '102',
  ACCOUNTS_RECEIVABLE = '120',

  // Liabilities
  ACCOUNTS_PAYABLE = '320',
  TAX_PAYABLE = '360',

  // Equity
  OWNERS_EQUITY = '500',

  // Revenue
  SALES_REVENUE = '600',
  SERVICE_REVENUE = '601',

  // Expenses
  OPERATING_EXPENSE = '770',
  SALARIES_EXPENSE = '720',
  RENT_EXPENSE = '730',
}

export interface LedgerAccountEntity {
  id: string;
  code: string;
  name: string;
  type: AccountType;
  balance: number;
  description?: string;
  createdAt: Date;
  updatedAt: Date;
}

export class LedgerAccount {
  static fromRow(row: any): LedgerAccountEntity {
    return {
      id: row.id,
      code: row.code,
      name: row.name,
      type: row.type as AccountType,
      balance: parseFloat(row.balance),
      description: row.description,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }
}

export enum EntryType {
  DEBIT = 'DEBIT',
  CREDIT = 'CREDIT',
}

export interface LedgerEntryEntity {
  id: string;
  transactionId: string;
  accountId: string;
  amount: number;
  type: EntryType;
  description: string;
  date: Date;
  referenceType?: string; // e.g., 'INVOICE', 'PAYMENT'
  referenceId?: string;
  createdAt: Date;
}

export class LedgerEntry {
  static fromRow(row: any): LedgerEntryEntity {
    return {
      id: row.id,
      transactionId: row.transaction_id,
      accountId: row.account_id,
      amount: parseFloat(row.amount),
      type: row.type as EntryType,
      description: row.description,
      date: row.date,
      referenceType: row.reference_type,
      referenceId: row.reference_id,
      createdAt: row.created_at,
    };
  }
}

import { Injectable } from '@nestjs/common';
import { PoolClient } from 'pg';
import { DatabasePool } from '../../../../database/pool';
import { BaseQuery } from '../../../../database/query/base-query';
import {
  AccountType,
  LedgerAccount,
  LedgerAccountEntity,
} from '../domain/ledger-account.entity';
import {
  EntryType,
  LedgerEntry,
  LedgerEntryEntity,
} from '../domain/ledger-entry.entity';

@Injectable()
export class LedgerRepository {
  constructor(private readonly db: DatabasePool) {}

  async createAccount(
    data: {
      code: string;
      name: string;
      type: AccountType;
      description?: string;
    },
    client?: PoolClient,
  ): Promise<LedgerAccountEntity> {
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const sql = `
                INSERT INTO ledger_accounts (code, name, type, description)
                VALUES ($1, $2, $3, $4)
                RETURNING *;
            `;
      const params = [data.code, data.name, data.type, data.description];
      const row = await BaseQuery.queryOne<any>(dbClient, sql, params);
      return LedgerAccount.fromRow(row);
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async findAccountByCode(
    code: string,
    client?: PoolClient,
  ): Promise<LedgerAccountEntity | null> {
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const sql = `SELECT * FROM ledger_accounts WHERE code = $1`;
      const row = await BaseQuery.queryOne<any>(dbClient, sql, [code]);
      return row ? LedgerAccount.fromRow(row) : null;
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async createEntry(
    data: {
      transactionId: string;
      accountId: string;
      amount: number;
      type: EntryType;
      description: string;
      referenceType?: string;
      referenceId?: string;
    },
    client: PoolClient,
  ): Promise<LedgerEntryEntity> {
    const sql = `
            INSERT INTO ledger_entries (
                transaction_id, account_id, amount, type, description, 
                reference_type, reference_id
            )
            VALUES ($1, $2, $3, $4, $5, $6, $7)
            RETURNING *;
        `;
    const params = [
      data.transactionId,
      data.accountId,
      data.amount,
      data.type,
      data.description,
      data.referenceType,
      data.referenceId,
    ];
    const row = await BaseQuery.queryOne<any>(client, sql, params);

    // Update Account Balance
    // For Assets/Expenses: Debit increases (+), Credit decreases (-)
    // For Liab/Equity/Revenue: Credit increases (+), Debit decreases (-)
    // But simply: Standard balance handling often updates 'balance' column based on normal balance.
    // Or simpler: Just store balance as net value.
    // Let's assume balance is stored as signed value?
    // Or we calculate it on fly.
    // The schema has 'balance' column. I should update it.

    // Determine sign based on Account Type and Entry Type
    // This logic fits better in Service, but atomic update in Repo is good.
    // I will just fetch account type to decide sign? Or pass it?
    // For now, I will NOT update balance here to keep it simple.
    // Balance can be aggregated from entries or updated by trigger or service.
    // Given complexity, I'll count on Service handling connection or triggers.
    // Actually, let's implement updateBalance in Service calling a Repo method.

    return LedgerEntry.fromRow(row);
  }

  // Helper to update account balance atomically
  async updateAccountBalance(
    accountId: string,
    amountDelta: number,
    client: PoolClient,
  ): Promise<void> {
    const sql = `
            UPDATE ledger_accounts 
            SET balance = balance + $2, updated_at = NOW()
            WHERE id = $1
        `;
    await BaseQuery.execute(client, sql, [accountId, amountDelta]);
  }
}

import { ApiPropertyOptional } from '@nestjs/swagger';
