      SystemEvents.AUDIT_LOG_CREATED,
      expect.objectContaining({
        entityId: 'refund-1',
        action: 'OTHER',
      }),
    );
    expect(eventEmitter.emit).toHaveBeenCalledWith(
      SystemEvents.PAYMENT_REFUND_CREATED,
      expect.objectContaining({
        refundPaymentId: 'refund-1',
        actorUserId: 'admin-1',
      }),
    );
  });
});

import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { DatabasePool } from '../../../../database/pool';
import { CreatePaymentDto } from '../api/dto/create-payment.dto';
import { UpdatePaymentDto } from '../api/dto/update-payment.dto';
import { RefundPaymentDto } from '../api/dto/refund-payment.dto';
import { ListPaymentsQueryDto } from '../api/dto/list-payments.query.dto';
import {
  PaymentAuditFilters,
  PaymentAuditPage,
  PaymentEntity,
} from '../domain/payment.entity';
import { ProcessPaymentUseCase } from './usecases/process-payment.usecase';
import { ListPaymentsByInvoiceUseCase } from './usecases/list-payments-by-invoice.usecase';
import { PaymentsRepository } from '../infrastructure/payments.repository';
import { InvoicesRepository } from '../../invoices/infrastructure/invoices.repository';
import {
  InvoiceEntity,
  InvoiceStatus,
} from '../../invoices/domain/invoice.entity';
import { PoolClient } from 'pg';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { SystemEvents } from '../../../../shared/events/event.constants';
import { Role } from '../../../../shared/enums/role.enum';
import { ExpenseEntity } from '../../expenses/domain/expense.entity';
import { ExpensesRepository } from '../../expenses/infrastructure/expenses.repository';

@Injectable()
export class PaymentsService {
  constructor(
    private readonly dbPool: DatabasePool,
    private readonly paymentsRepository: PaymentsRepository,
    private readonly invoicesRepository: InvoicesRepository,
    private readonly expensesRepository: ExpensesRepository,
    private readonly processPaymentUseCase: ProcessPaymentUseCase,
    private readonly listPaymentsByInvoiceUseCase: ListPaymentsByInvoiceUseCase,
    private readonly eventEmitter: EventEmitter2,
  ) {}

  async create(
    createPaymentDto: CreatePaymentDto,
    userId: string,
  ): Promise<PaymentEntity> {
    const payment = await this.processPaymentUseCase.execute(
      createPaymentDto,
      userId,
    );

    this.emitPaymentAudit({
      action: 'CREATE',
      userId,
      paymentId: payment.id,
      invoiceId: payment.invoiceId,
      details: {
        eventType: 'PAYMENT_CREATED',
        invoiceId: payment.invoiceId,
        paymentId: payment.id,
        amount: payment.amount,
        method: payment.method,
        paymentDate: payment.paymentDate,
        reference: payment.reference ?? null,
        notes: payment.notes ?? null,
        receiptUrl: payment.receiptUrl ?? null,
      },
    });

    return payment;
  }

  async getPaymentsByInvoice(invoiceId: string): Promise<PaymentEntity[]> {
    return this.listPaymentsByInvoiceUseCase.execute(invoiceId);
  }

  async getPayments(query: ListPaymentsQueryDto): Promise<PaymentEntity[]> {
    return this.paymentsRepository.findAll(query);
  }

  async update(
    paymentId: string,
    updatePaymentDto: UpdatePaymentDto,
    userId: string,
  ): Promise<PaymentEntity> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();

    try {
      await client.query('BEGIN');

      const existing = await this.paymentsRepository.findById(
        paymentId,
        client,
      );
      if (!existing) {
        throw new NotFoundException('Payment not found');
      }

      const updated = await this.paymentsRepository.update(
        paymentId,
        {
          amount: updatePaymentDto.amount,
          method: updatePaymentDto.method,
          paymentDate: updatePaymentDto.paymentDate
            ? new Date(updatePaymentDto.paymentDate)
            : undefined,
          reference: updatePaymentDto.reference,
          notes: updatePaymentDto.notes,
          receiptUrl: updatePaymentDto.receiptUrl,
        },
        client,
      );

      if (!updated) {
        throw new NotFoundException('Payment not found');
      }

      await this.syncInvoiceStatus(existing.invoiceId, client);

      await client.query('COMMIT');

      this.emitPaymentAudit({
        action: 'UPDATE',
        userId,
        paymentId: updated.id,
        invoiceId: existing.invoiceId,
        details: {
          eventType: 'PAYMENT_UPDATED',
          invoiceId: existing.invoiceId,
          paymentId: updated.id,
          changedFields: [
            updatePaymentDto.amount !== undefined ? 'amount' : null,
            updatePaymentDto.method !== undefined ? 'method' : null,
            updatePaymentDto.paymentDate !== undefined ? 'paymentDate' : null,
            updatePaymentDto.reference !== undefined ? 'reference' : null,
            updatePaymentDto.notes !== undefined ? 'notes' : null,
            updatePaymentDto.receiptUrl !== undefined ? 'receiptUrl' : null,
          ].filter(Boolean),
          before: {
            amount: existing.amount,
            method: existing.method,
            paymentDate: existing.paymentDate,
            reference: existing.reference ?? null,
            notes: existing.notes ?? null,
            receiptUrl: existing.receiptUrl ?? null,
          },
          after: {
            amount: updated.amount,
            method: updated.method,
            paymentDate: updated.paymentDate,
            reference: updated.reference ?? null,
            notes: updated.notes ?? null,
            receiptUrl: updated.receiptUrl ?? null,
          },
        },
      });

      return updated;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  async remove(paymentId: string, userId: string): Promise<void> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();

    try {
      await client.query('BEGIN');

      const existing = await this.paymentsRepository.findById(
        paymentId,
        client,
      );
      if (!existing) {
        throw new NotFoundException('Payment not found');
      }

      const removed = await this.paymentsRepository.remove(paymentId, client);
      if (!removed) {
        throw new NotFoundException('Payment not found');
      }

      await this.syncInvoiceStatus(existing.invoiceId, client);

      await client.query('COMMIT');

      this.emitPaymentAudit({
        action: 'DELETE',
        userId,
        paymentId: existing.id,
        invoiceId: existing.invoiceId,
        details: {
          eventType: 'PAYMENT_DELETED',
          invoiceId: existing.invoiceId,
          paymentId: existing.id,
          deletedPayment: {
            amount: existing.amount,
            method: existing.method,
            paymentDate: existing.paymentDate,
            reference: existing.reference ?? null,
            notes: existing.notes ?? null,
            receiptUrl: existing.receiptUrl ?? null,
          },
        },
      });

      try {
        const targetUserIds =
          await this.resolveFinanceNotificationTargets(userId);
        const [invoice, actorName] = await Promise.all([
          this.invoicesRepository.findById(existing.invoiceId),
          this.paymentsRepository.findUserDisplayNameById(userId),
        ]);
        this.eventEmitter.emit(SystemEvents.PAYMENT_DELETED, {
          targetUserIds,
          actorUserId: userId,
          actorName,
          invoiceId: existing.invoiceId,
          invoiceNumber: invoice?.invoiceNumber,
          paymentId: existing.id,
          amount: existing.amount,
        });
      } catch {
        // Notification failures should not break a successful delete transaction.
      }
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  async refund(
    paymentId: string,
    refundPaymentDto: RefundPaymentDto,
    userId: string,
  ): Promise<PaymentEntity> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();

    try {
      await client.query('BEGIN');

      const original = await this.paymentsRepository.findById(
        paymentId,
        client,
      );
      if (!original) {
        throw new NotFoundException('Payment not found');
      }

      if (original.amount <= 0) {
        throw new BadRequestException(
          'Refund can only be created from positive payments',
        );
      }

      const refundAmount = refundPaymentDto.amount ?? original.amount;
      if (refundAmount <= 0) {
        throw new BadRequestException(
          'Refund amount must be greater than zero',
        );
      }
      if (refundAmount > original.amount) {
        throw new BadRequestException(
          'Refund amount cannot exceed original payment amount',
        );
      }

      const referenceBase = original.reference
        ? `${original.reference}-REFUND`
        : `REFUND-${original.id.slice(0, 8)}`;
      const reason = refundPaymentDto.reason?.trim();

      const refund = await this.paymentsRepository.create(
        {
          invoiceId: original.invoiceId,
          amount: -Math.abs(refundAmount),
          method: original.method,
          paymentDate: refundPaymentDto.paymentDate
            ? new Date(refundPaymentDto.paymentDate)
            : new Date(),
          reference: referenceBase,
          notes: reason
            ? `Iade: ${reason}`
            : `Iade islemi (kaynak odeme: ${original.id})`,
          receiptUrl: refundPaymentDto.receiptUrl?.trim() || undefined,
          recordedBy: userId,
        },
        client,
      );

      await this.syncInvoiceStatus(original.invoiceId, client);

      await client.query('COMMIT');

      this.emitPaymentAudit({
        action: 'OTHER',
        userId,
        paymentId: refund.id,
        invoiceId: original.invoiceId,
        details: {
          eventType: 'PAYMENT_REFUND_CREATED',
          invoiceId: original.invoiceId,
          sourcePaymentId: original.id,
          refundPaymentId: refund.id,
          refundAmount: refund.amount,
          method: refund.method,
          paymentDate: refund.paymentDate,
          reason: reason ?? null,
          receiptUrl: refund.receiptUrl ?? null,
        },
      });

      try {
        const targetUserIds =
          await this.resolveFinanceNotificationTargets(userId);
        const [invoice, actorName] = await Promise.all([
          this.invoicesRepository.findById(original.invoiceId),
          this.paymentsRepository.findUserDisplayNameById(userId),
        ]);
        this.eventEmitter.emit(SystemEvents.PAYMENT_REFUND_CREATED, {
          targetUserIds,
          actorUserId: userId,
          actorName,
          invoiceId: original.invoiceId,
          invoiceNumber: invoice?.invoiceNumber,
          sourcePaymentId: original.id,
          refundPaymentId: refund.id,
          amount: Math.abs(refund.amount),
        });
      } catch {
        // Notification failures should not break a successful refund transaction.
      }

      return refund;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  private async syncInvoiceStatus(
    invoiceId: string,
    client: PoolClient,
  ): Promise<void> {
    const invoice = await this.invoicesRepository.findById(invoiceId, client);
    if (!invoice) return;

    const totalPaid = await this.paymentsRepository.sumPaymentsByInvoiceId(
      invoiceId,
      client,
    );
    const nextStatus = this.resolveInvoiceStatus(invoice, totalPaid);

    if (nextStatus !== invoice.status) {
      await this.invoicesRepository.updateStatus(invoiceId, nextStatus, client);
    }
  }

  private resolveInvoiceStatus(
    invoice: InvoiceEntity,
    totalPaid: number,
  ): InvoiceStatus {
    if (invoice.status === InvoiceStatus.CANCELLED) {
      return InvoiceStatus.CANCELLED;
    }

    if (totalPaid >= invoice.total) {
      return InvoiceStatus.PAID;
    }

    if (totalPaid > 0) {
      return InvoiceStatus.PARTIALLY_PAID;
    }

    if (invoice.status === InvoiceStatus.DRAFT) {
      return InvoiceStatus.DRAFT;
    }

    if (invoice.dueDate && new Date(invoice.dueDate) < new Date()) {
      return InvoiceStatus.OVERDUE;
    }

    return InvoiceStatus.SENT;
  }

  async getAuditByInvoice(
    invoiceId: string,
    filters?: PaymentAuditFilters,
  ): Promise<PaymentAuditPage> {
    return this.paymentsRepository.findAuditByInvoiceId(invoiceId, filters);
  }

  async getCashflowOverview(months?: number) {
    const safeMonths = Number.isFinite(months)
      ? Math.max(1, Math.min(24, Number(months)))
      : 6;
    const monthKeys = this.getRecentMonthKeys(safeMonths);
    const startDate = this.monthKeyToDate(monthKeys[0]);
    const endDate = new Date();
    endDate.setDate(1);
    endDate.setHours(0, 0, 0, 0);
    endDate.setMonth(endDate.getMonth() + 1);

    const [invoices, expenses, inflowByMonth] = await Promise.all([
      this.invoicesRepository.findAll({ page: 1, limit: 1000 }),
      this.expensesRepository.findAll(2000, 0),
      this.paymentsRepository.sumByMonthRange(startDate, endDate),
    ]);

    const paymentByInvoice = await this.paymentsRepository.sumByInvoiceIds(
      invoices.map((invoice) => invoice.id),
    );

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const invoiceBalances = invoices.map((invoice) => {
      const collected = paymentByInvoice[invoice.id] || 0;
      const outstanding = Math.max(0, Number(invoice.total || 0) - collected);
      const dueDateObj = this.toDateOnly(invoice.dueDate as any);
      const overdueDays =
        dueDateObj && outstanding > 0 && dueDateObj.getTime() < today.getTime()
          ? Math.floor((today.getTime() - dueDateObj.getTime()) / 86_400_000)
          : 0;

      return {
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        clientName: invoice.clientName || '',
        dueDate: invoice.dueDate || null,
        outstanding,
        overdueDays,
      };
    });

    const paidExpenses = expenses.filter(
      (expense) => String(expense.status).toUpperCase() === 'PAID',
    );
    const chartOutflowMap: Record<string, number> = {};
    expenses
      .filter((expense) => {
        const status = String(expense.status).toUpperCase();
        return status === 'PAID' || status === 'APPROVED';
      })
      .forEach((expense) => {
        const date = this.toDateOnly(expense.expenseDate as any);
        if (!date) return;
        const key = this.getMonthKey(date);
        chartOutflowMap[key] =
          (chartOutflowMap[key] || 0) + Number(expense.amount || 0);
      });

    const chart = monthKeys.map((key) => {
      const inflow = inflowByMonth[key] || 0;
      const outflow = chartOutflowMap[key] || 0;
      return {
        key,
        label: this.getMonthLabel(key),
        inflow,
        outflow,
        net: inflow - outflow,
      };
    });

    const overdueInvoices = invoiceBalances
      .filter((invoice) => invoice.overdueDays > 0 && invoice.outstanding > 0)
      .sort((a, b) => b.overdueDays - a.overdueDays)
      .slice(0, 8);

    const upcomingReceivables = invoiceBalances
      .filter((invoice) => {
        const dueDateObj = this.toDateOnly(invoice.dueDate as any);
        return (
          !!dueDateObj &&
          invoice.outstanding > 0 &&
          dueDateObj.getTime() >= today.getTime()
        );
      })
      .sort((a, b) => {
        const aDate =
          this.toDateOnly(a.dueDate as any)?.getTime() ||
          Number.MAX_SAFE_INTEGER;
        const bDate =
          this.toDateOnly(b.dueDate as any)?.getTime() ||
          Number.MAX_SAFE_INTEGER;
        return aDate - bDate;
      })
      .slice(0, 8);

    const upcomingExpensePayments = expenses
      .filter((expense) => {
        const status = String(expense.status).toUpperCase();
        if (status !== 'PENDING' && status !== 'APPROVED') return false;
        const expenseDate = this.toDateOnly(expense.expenseDate as any);
        return !!expenseDate && expenseDate.getTime() >= today.getTime();
      })
      .sort((a, b) => {
        const aDate =
          this.toDateOnly(a.expenseDate as any)?.getTime() ||
          Number.MAX_SAFE_INTEGER;
        const bDate =
          this.toDateOnly(b.expenseDate as any)?.getTime() ||
          Number.MAX_SAFE_INTEGER;
        return aDate - bDate;
      })
      .slice(0, 8)
      .map((expense) => this.toExpenseCard(expense));

    const totalInflow = Object.values(paymentByInvoice).reduce(
      (sum, amount) => sum + Number(amount || 0),
      0,
    );
    const totalOutflow = paidExpenses.reduce(
      (sum, expense) => sum + Number(expense.amount || 0),
      0,
    );
    const outstanding = invoiceBalances.reduce(
      (sum, invoice) => sum + invoice.outstanding,
      0,
    );
    const overdueAmount = overdueInvoices.reduce(
      (sum, invoice) => sum + invoice.outstanding,
      0,
    );
    const upcomingAmount = invoiceBalances
      .filter((invoice) => {
        const dueDateObj = this.toDateOnly(invoice.dueDate as any);
        if (!dueDateObj || invoice.outstanding <= 0) return false;
        const diffDays = Math.ceil(
          (dueDateObj.getTime() - today.getTime()) / 86_400_000,
        );
        return diffDays >= 0 && diffDays <= 14;
      })
      .reduce((sum, invoice) => sum + invoice.outstanding, 0);

    return {
      months: safeMonths,
      kpis: {
        totalInflow,
        totalOutflow,
        netCash: totalInflow - totalOutflow,
        outstanding,
        overdueAmount,
        overdueCount: overdueInvoices.length,
        upcomingAmount,
      },
      chart,
      overdueInvoices,
      upcomingReceivables,
      upcomingExpensePayments,
    };
  }

  private emitPaymentAudit(payload: {
    action: 'CREATE' | 'UPDATE' | 'DELETE' | 'OTHER';
    userId?: string;
    paymentId: string;
    invoiceId: string;
    details: Record<string, any>;
  }): void {
    this.eventEmitter.emit(SystemEvents.AUDIT_LOG_CREATED, {
      entityName: 'PAYMENT',
      entityId: payload.paymentId,
      action: payload.action,
      userId: payload.userId,
      details: {
        ...payload.details,
        invoiceId: payload.invoiceId,
      },
    });
  }

  private async resolveFinanceNotificationTargets(
    actorUserId?: string,
  ): Promise<string[]> {
    const financeLeads = await this.paymentsRepository.findUserIdsByRoles([
      Role.ADMIN,
      Role.MANAGER,
      Role.ACCOUNTING,
      Role.SOCIAL_MEDIA,
      'SEO',
    ]);

    return Array.from(
      new Set(
        [...financeLeads, actorUserId].filter(
          (value): value is string => !!value && value.length > 0,
        ),
      ),
    );
  }

  private toDateOnly(value?: string | Date | null): Date | null {
    if (!value) return null;
    const date = value instanceof Date ? new Date(value) : new Date(value);
    if (Number.isNaN(date.getTime())) return null;
    date.setHours(0, 0, 0, 0);
    return date;
  }

  private getMonthKey(date: Date): string {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    return `${year}-${month}`;
  }

  private getMonthLabel(key: string): string {
    const [year, month] = key.split('-');
    return `${month}.${year}`;
  }

  private monthKeyToDate(key: string): Date {
    const [year, month] = key.split('-').map((val) => Number(val));
    return new Date(year, month - 1, 1);
  }

  private getRecentMonthKeys(monthCount: number): string[] {
    const now = new Date();
    now.setDate(1);
    now.setHours(0, 0, 0, 0);
    const keys: string[] = [];
    for (let i = monthCount - 1; i >= 0; i -= 1) {
      const cursor = new Date(now);
      cursor.setMonth(now.getMonth() - i);
      keys.push(this.getMonthKey(cursor));
    }
    return keys;
  }

  private toExpenseCard(expense: ExpenseEntity) {
    return {
      id: expense.id,
      description: expense.description,
      department: expense.department,
      expenseDate: expense.expenseDate,
      status: expense.status,
      amount: Number(expense.amount || 0),
    };
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { NotFoundException } from '@nestjs/common';
import { ProcessPaymentUseCase } from './process-payment.usecase';
import { PaymentsRepository } from '../../infrastructure/payments.repository';
import { InvoicesRepository } from '../../../invoices/infrastructure/invoices.repository';
import { DatabasePool } from '../../../../../database/pool';
import { InvoiceStatus } from '../../../invoices/domain/invoice.entity';
import { PaymentMethod } from '../../domain/payment.entity';

describe('ProcessPaymentUseCase', () => {
  let useCase: ProcessPaymentUseCase;
  let paymentsRepo: Partial<jest.Mocked<PaymentsRepository>>;
  let invoicesRepo: Partial<jest.Mocked<InvoicesRepository>>;
  let dbPool: Partial<DatabasePool>;
  let mockClient: any;

  const mockInvoice: any = {
    id: 'inv-1',
    invoiceNumber: 'INV-000001-001',
    status: InvoiceStatus.SENT,
    total: 1000,
  };

  const mockDto: any = {
    invoiceId: 'inv-1',
    amount: 500,
    method: PaymentMethod.BANK_TRANSFER,
    paymentDate: '2026-01-20',
    reference: 'REF-123',
    notes: 'Partial payment',
  };

  beforeEach(async () => {
    mockClient = {
      query: jest.fn(),
      release: jest.fn(),
    };

    dbPool = {
      getPool: jest.fn().mockReturnValue({
        connect: jest.fn().mockResolvedValue(mockClient),
      }),
    };

    paymentsRepo = {
      create: jest.fn(),
      sumPaymentsByInvoiceId: jest.fn(),
    };

    invoicesRepo = {
      findById: jest.fn(),
      updateStatus: jest.fn(),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        ProcessPaymentUseCase,
        { provide: PaymentsRepository, useValue: paymentsRepo },
        { provide: InvoicesRepository, useValue: invoicesRepo },
        { provide: DatabasePool, useValue: dbPool },
      ],
    }).compile();

    useCase = module.get<ProcessPaymentUseCase>(ProcessPaymentUseCase);
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('should be defined', () => {
    expect(useCase).toBeDefined();
  });

  describe('execute', () => {
    it('should process payment and mark invoice as PARTIALLY_PAID', async () => {
      const createdPayment = { id: 'pay-1', ...mockDto };

      invoicesRepo.findById.mockResolvedValue(mockInvoice);
      paymentsRepo.create.mockResolvedValue(createdPayment);
      paymentsRepo.sumPaymentsByInvoiceId.mockResolvedValue(500); // 500 < 1000

      const result = await useCase.execute(mockDto, 'user-1');

      expect(result).toEqual(createdPayment);
      expect(mockClient.query).toHaveBeenCalledWith('BEGIN');
      expect(mockClient.query).toHaveBeenCalledWith('COMMIT');
      expect(invoicesRepo.updateStatus).toHaveBeenCalledWith(
        'inv-1',
        InvoiceStatus.PARTIALLY_PAID,
        mockClient,
      );
      expect(mockClient.release).toHaveBeenCalled();
    });

    it('should mark invoice as PAID when fully paid', async () => {
      invoicesRepo.findById.mockResolvedValue(mockInvoice);
      paymentsRepo.create.mockResolvedValue({ id: 'pay-2' } as any);
      paymentsRepo.sumPaymentsByInvoiceId.mockResolvedValue(1000); // 1000 >= 1000

      await useCase.execute(mockDto, 'user-1');

      expect(invoicesRepo.updateStatus).toHaveBeenCalledWith(
        'inv-1',
        InvoiceStatus.PAID,
        mockClient,
      );
    });

    it('should mark invoice as PAID when overpaid', async () => {
      invoicesRepo.findById.mockResolvedValue(mockInvoice);
      paymentsRepo.create.mockResolvedValue({ id: 'pay-3' } as any);
      paymentsRepo.sumPaymentsByInvoiceId.mockResolvedValue(1200); // 1200 > 1000

      await useCase.execute(mockDto, 'user-1');

      expect(invoicesRepo.updateStatus).toHaveBeenCalledWith(
        'inv-1',
        InvoiceStatus.PAID,
        mockClient,
      );
    });

    it('should not update status if it has not changed', async () => {
      const alreadyPartialInvoice = {
        ...mockInvoice,
        status: InvoiceStatus.PARTIALLY_PAID,
      };
      invoicesRepo.findById.mockResolvedValue(alreadyPartialInvoice);
      paymentsRepo.create.mockResolvedValue({ id: 'pay-4' } as any);
      paymentsRepo.sumPaymentsByInvoiceId.mockResolvedValue(500); // still partially paid

      await useCase.execute(mockDto, 'user-1');

      expect(invoicesRepo.updateStatus).not.toHaveBeenCalled();
    });

    it('should throw NotFoundException when invoice not found', async () => {
      invoicesRepo.findById.mockResolvedValue(null);

      await expect(useCase.execute(mockDto, 'user-1')).rejects.toThrow(
        NotFoundException,
      );

      expect(mockClient.query).toHaveBeenCalledWith('ROLLBACK');
      expect(mockClient.release).toHaveBeenCalled();
    });

    it('should rollback and release client on error', async () => {
      invoicesRepo.findById.mockResolvedValue(mockInvoice);
      paymentsRepo.create.mockRejectedValue(new Error('DB Error'));

      await expect(useCase.execute(mockDto, 'user-1')).rejects.toThrow(
        'DB Error',
      );

      expect(mockClient.query).toHaveBeenCalledWith('ROLLBACK');
      expect(mockClient.release).toHaveBeenCalled();
    });
  });
});

export enum PaymentMethod {
  BANK_TRANSFER = 'BANK_TRANSFER',
  CREDIT_CARD = 'CREDIT_CARD',
  CASH = 'CASH',
  OTHER = 'OTHER',
}

export interface PaymentEntity {
  id: string;
  invoiceId: string;
  amount: number;
  paymentDate: Date;
  method: PaymentMethod;
  reference?: string;
  notes?: string;
  receiptUrl?: string;
  recordedBy: string;
  recordedByName?: string;
  createdAt: Date;

  // joined
  invoiceNumber?: string;
  clientName?: string;
}

export interface PaymentAuditEntity {
  id: string;
  paymentId?: string;
  invoiceId?: string;
  action: 'CREATE' | 'UPDATE' | 'DELETE' | 'OTHER';
  userId?: string;
  userName?: string;
  details?: Record<string, any>;
  createdAt: Date;
}

export interface PaymentAuditFilters {
  page?: number;
  limit?: number;
  sortDirection?: 'ASC' | 'DESC';
  eventType?: string;
  startDate?: string;
  endDate?: string;
  userId?: string;
}

export interface PaymentAuditPage {
  data: PaymentAuditEntity[];
  total: number;
  page: number;
  limit: number;
}

export class Payment {
  static fromRow(row: any): PaymentEntity {
    const paymentDateRaw = row.payment_date ?? row.created_at ?? new Date();
    const createdAtRaw = row.created_at ?? row.payment_date ?? new Date();

    return {
      id: row.id,
      invoiceId: row.invoice_id,
      amount: parseFloat(row.amount),
      paymentDate: paymentDateRaw,
      method: (row.method as PaymentMethod) || PaymentMethod.OTHER,
      reference: row.reference,
      notes: row.notes,
      receiptUrl: row.receipt_url ?? row.receiptUrl ?? undefined,
      recordedBy: row.recorded_by ?? '',
      recordedByName: row.recorded_by_name ?? undefined,
      createdAt: createdAtRaw,
      invoiceNumber: row.invoice_number,
      clientName: row.client_name,
    };
  }
}

import { Injectable } from '@nestjs/common';
import { PoolClient } from 'pg';
import { DatabasePool } from '../../../../database/pool';
import { BaseQuery } from '../../../../database/query/base-query';
import {
  Payment,
  PaymentAuditEntity,
  PaymentAuditFilters,
  PaymentAuditPage,
  PaymentEntity,
} from '../domain/payment.entity';
import { ListPaymentsQueryDto } from '../api/dto/list-payments.query.dto';

interface PaymentsSchemaSnapshot {
  hasPaymentDate: boolean;
  hasReference: boolean;
  hasNotes: boolean;
  hasReceiptUrl: boolean;
  hasRecordedBy: boolean;
  hasCreatedAt: boolean;
}

@Injectable()
export class PaymentsRepository {
  private paymentsSchemaCache: PaymentsSchemaSnapshot | null = null;

  constructor(private readonly db: DatabasePool) {}

  async create(
    paymentData: Partial<PaymentEntity>,
    client: PoolClient,
  ): Promise<PaymentEntity> {
    const schema = await this.getPaymentsSchema(client);

    const columns = ['invoice_id', 'amount', 'method'];
    const values: any[] = [
      paymentData.invoiceId,
      paymentData.amount,
      paymentData.method,
    ];

    if (schema.hasPaymentDate) {
      columns.push('payment_date');
      values.push(paymentData.paymentDate ?? new Date());
    }
    if (schema.hasReference) {
      columns.push('reference');
      values.push(paymentData.reference ?? null);
    }
    if (schema.hasNotes) {
      columns.push('notes');
      values.push(paymentData.notes ?? null);
    }
    if (schema.hasReceiptUrl) {
      columns.push('receipt_url');
      values.push(paymentData.receiptUrl ?? null);
    }
    if (schema.hasRecordedBy) {
      columns.push('recorded_by');
      values.push(paymentData.recordedBy ?? null);
    }
    if (schema.hasCreatedAt) {
      columns.push('created_at');
    }

    const placeholders = values.map((_, index) => `$${index + 1}`);
    if (schema.hasCreatedAt) {
      placeholders.push('NOW()');
    }

    const row = await BaseQuery.queryOne<any>(
      client,
      `
        INSERT INTO payments (${columns.join(', ')})
        VALUES (${placeholders.join(', ')})
        RETURNING *;
      `,
      values,
    );

    return Payment.fromRow(row);
  }

  async findById(
    id: string,
    client?: PoolClient,
  ): Promise<PaymentEntity | null> {
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const schema = await this.getPaymentsSchema(dbClient);
      const sql = schema.hasRecordedBy
        ? `
            SELECT
              p.*,
              COALESCE(
                NULLIF(TRIM(CONCAT_WS(' ', u.first_name, u.last_name)), ''),
                u.email,
                'Sistem'
              ) AS recorded_by_name
            FROM payments p
            LEFT JOIN users u ON u.id = p.recorded_by
            WHERE p.id = $1
          `
        : `
            SELECT p.*
            FROM payments p
            WHERE p.id = $1
          `;
      const row = await BaseQuery.queryOne<any>(dbClient, sql, [id]);
      return row ? Payment.fromRow(row) : null;
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async findByInvoiceId(invoiceId: string): Promise<PaymentEntity[]> {
    const client = await this.db.getPool().connect();
    try {
      const schema = await this.getPaymentsSchema(client);
      const orderBy = schema.hasPaymentDate
        ? 'payment_date DESC'
        : schema.hasCreatedAt
          ? 'created_at DESC'
          : 'id DESC';

      const sql = schema.hasRecordedBy
        ? `
            SELECT
              p.*,
              COALESCE(
                NULLIF(TRIM(CONCAT_WS(' ', u.first_name, u.last_name)), ''),
                u.email,
                'Sistem'
              ) AS recorded_by_name
            FROM payments p
            LEFT JOIN users u ON u.id = p.recorded_by
            WHERE p.invoice_id = $1
            ORDER BY p.${orderBy}
          `
        : `
            SELECT p.*
            FROM payments p
            WHERE p.invoice_id = $1
            ORDER BY p.${orderBy}
          `;
      const rows = await BaseQuery.queryMany<any>(client, sql, [invoiceId]);
      return rows.map((row) => Payment.fromRow(row));
    } finally {
      client.release();
    }
  }

  async findAll(filters?: ListPaymentsQueryDto): Promise<PaymentEntity[]> {
    const client = await this.db.getPool().connect();
    try {
      const schema = await this.getPaymentsSchema(client);
      const conditions: string[] = [];
      const params: any[] = [];
      let nextParam = 1;

      if (filters?.invoiceId) {
        conditions.push(`p.invoice_id = $${nextParam++}`);
        params.push(filters.invoiceId);
      }

      if (filters?.method) {
        conditions.push(`p.method = $${nextParam++}`);
        params.push(filters.method);
      }

      const dateExpr = schema.hasPaymentDate
        ? `COALESCE(p.payment_date, p.created_at)::date`
        : `p.created_at::date`;

      if (filters?.startDate) {
        conditions.push(`${dateExpr} >= $${nextParam++}::date`);
        params.push(filters.startDate);
      }

      if (filters?.endDate) {
        conditions.push(
          `${dateExpr} < ($${nextParam++}::date + INTERVAL '1 day')`,
        );
        params.push(filters.endDate);
      }

      if (filters?.search?.trim()) {
        const query = `%${filters.search.trim()}%`;
        const referenceExpr = schema.hasReference
          ? `COALESCE(p.reference, '')`
          : `''`;
        conditions.push(
          `(
            COALESCE(i.invoice_number, '') ILIKE $${nextParam}
            OR COALESCE(c.company_name, '') ILIKE $${nextParam}
            OR ${referenceExpr} ILIKE $${nextParam}
          )`,
        );
        params.push(query);
        nextParam += 1;
      }

      const whereClause =
        conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
      const page = filters?.page && filters.page > 0 ? filters.page : 1;
      const limit =
        filters?.limit && filters.limit > 0
          ? Math.min(filters.limit, 1000)
          : 200;
      const offset = (page - 1) * limit;
      const orderBy = schema.hasPaymentDate
        ? schema.hasCreatedAt
          ? 'COALESCE(p.payment_date, p.created_at) DESC'
          : 'p.payment_date DESC'
        : schema.hasCreatedAt
          ? 'p.created_at DESC'
          : 'p.id DESC';

      const sql = schema.hasRecordedBy
        ? `
            SELECT
              p.*,
              i.invoice_number,
              c.company_name AS client_name,
              COALESCE(
                NULLIF(TRIM(CONCAT_WS(' ', u.first_name, u.last_name)), ''),
                u.email,
                'Sistem'
              ) AS recorded_by_name
            FROM payments p
            LEFT JOIN invoices i ON i.id = p.invoice_id
            LEFT JOIN clients c ON c.id = i.client_id
            LEFT JOIN users u ON u.id = p.recorded_by
            ${whereClause}
            ORDER BY ${orderBy}
            LIMIT $${nextParam++}
            OFFSET $${nextParam++}
          `
        : `
            SELECT
              p.*,
              i.invoice_number,
              c.company_name AS client_name
            FROM payments p
            LEFT JOIN invoices i ON i.id = p.invoice_id
            LEFT JOIN clients c ON c.id = i.client_id
            ${whereClause}
            ORDER BY ${orderBy}
            LIMIT $${nextParam++}
            OFFSET $${nextParam++}
          `;

      params.push(limit, offset);
      const rows = await BaseQuery.queryMany<any>(client, sql, params);
      return rows.map((row) => Payment.fromRow(row));
    } finally {
      client.release();
    }
  }

  async update(
    id: string,
    paymentData: Partial<PaymentEntity>,
    client?: PoolClient,
  ): Promise<PaymentEntity | null> {
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const schema = await this.getPaymentsSchema(dbClient);
      const sets: string[] = [];
      const values: any[] = [];

      if (paymentData.amount !== undefined) {
        sets.push(`amount = $${values.length + 1}`);
        values.push(paymentData.amount);
      }
      if (paymentData.method !== undefined) {
        sets.push(`method = $${values.length + 1}`);
        values.push(paymentData.method);
      }
      if (paymentData.paymentDate !== undefined && schema.hasPaymentDate) {
        sets.push(`payment_date = $${values.length + 1}`);
        values.push(paymentData.paymentDate);
      }
      if (paymentData.reference !== undefined && schema.hasReference) {
        sets.push(`reference = $${values.length + 1}`);
        values.push(paymentData.reference ?? null);
      }
      if (paymentData.notes !== undefined && schema.hasNotes) {
        sets.push(`notes = $${values.length + 1}`);
        values.push(paymentData.notes ?? null);
      }
      if (paymentData.receiptUrl !== undefined && schema.hasReceiptUrl) {
        sets.push(`receipt_url = $${values.length + 1}`);
        values.push(paymentData.receiptUrl ?? null);
      }

      if (sets.length === 0) {
        return this.findById(id, dbClient);
      }

      values.push(id);
      const row = await BaseQuery.queryOne<any>(
        dbClient,
        `
          UPDATE payments
          SET ${sets.join(', ')}
          WHERE id = $${values.length}
          RETURNING *;
        `,
        values,
      );

      if (!row) return null;
      return this.findById(row.id, dbClient);
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async remove(id: string, client?: PoolClient): Promise<boolean> {
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const affected = await BaseQuery.execute(
        dbClient,
        `DELETE FROM payments WHERE id = $1`,
        [id],
      );
      return affected > 0;
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async sumPaymentsByInvoiceId(
    invoiceId: string,
    client?: PoolClient,
  ): Promise<number> {
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const sql = `SELECT COALESCE(SUM(amount), 0) as total_paid FROM payments WHERE invoice_id = $1`;
      const row = await BaseQuery.queryOne<any>(dbClient, sql, [invoiceId]);
      return parseFloat(row.total_paid);
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async sumByInvoiceIds(
    invoiceIds: string[],
    client?: PoolClient,
  ): Promise<Record<string, number>> {
    if (!invoiceIds.length) {
      return {};
    }

    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const rows = await BaseQuery.queryMany<{
        invoice_id: string;
        total_paid: string;
      }>(
        dbClient,
        `
          SELECT
            invoice_id::text AS invoice_id,
            COALESCE(SUM(amount), 0)::text AS total_paid
          FROM payments
          WHERE invoice_id::text = ANY($1::text[])
          GROUP BY invoice_id
        `,
        [invoiceIds],
      );

      const result: Record<string, number> = {};
      rows.forEach((row) => {
        result[row.invoice_id] = parseFloat(row.total_paid || '0');
      });
      return result;
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async sumByMonthRange(
    startDate: Date,
    endDate: Date,
    client?: PoolClient,
  ): Promise<Record<string, number>> {
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const schema = await this.getPaymentsSchema(dbClient);
      const dateExpr = schema.hasPaymentDate
        ? `COALESCE(payment_date, created_at)::date`
        : `created_at::date`;
      const rows = await BaseQuery.queryMany<{
        month_key: string;
        total_amount: string;
      }>(
        dbClient,
        `
          SELECT
            TO_CHAR(${dateExpr}, 'YYYY-MM') AS month_key,
            COALESCE(SUM(amount), 0)::text AS total_amount
          FROM payments
          WHERE ${dateExpr} >= $1::date
            AND ${dateExpr} < $2::date
          GROUP BY month_key
        `,
        [startDate, endDate],
      );

      const result: Record<string, number> = {};
      rows.forEach((row) => {
        result[row.month_key] = parseFloat(row.total_amount || '0');
      });
      return result;
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async findAuditByInvoiceId(
    invoiceId: string,
    filters?: PaymentAuditFilters,
    client?: PoolClient,
  ): Promise<PaymentAuditPage> {
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const conditions: string[] = [
        `UPPER(al.resource) = 'PAYMENT'`,
        `(al.new_data ->> 'invoiceId') = $1`,
      ];
      const params: any[] = [invoiceId];
      let nextParam = 2;

      if (filters?.eventType) {
        conditions.push(
          `COALESCE(
              NULLIF(UPPER(al.new_data ->> 'eventType'), ''),
              CASE UPPER(al.action)
                WHEN 'CREATE' THEN 'PAYMENT_CREATED'
                WHEN 'UPDATE' THEN 'PAYMENT_UPDATED'
                WHEN 'DELETE' THEN 'PAYMENT_DELETED'
                ELSE 'OTHER'
              END
            ) = $${nextParam++}`,
        );
        params.push(filters.eventType.toUpperCase());
      }

      if (filters?.startDate) {
        conditions.push(`al.created_at >= $${nextParam++}::date`);
        params.push(filters.startDate);
      }

      if (filters?.endDate) {
        conditions.push(
          `al.created_at < ($${nextParam++}::date + INTERVAL '1 day')`,
        );
        params.push(filters.endDate);
      }

      if (filters?.userId) {
        conditions.push(`al.user_id = $${nextParam++}`);
        params.push(filters.userId);
      }

      const page = filters?.page && filters.page > 0 ? filters.page : 1;
      const limit = filters?.limit && filters.limit > 0 ? filters.limit : 20;
      const offset = (page - 1) * limit;
      const sortDirection = filters?.sortDirection === 'ASC' ? 'ASC' : 'DESC';

      const countRow = await BaseQuery.queryOne<{ total: string }>(
        dbClient,
        `
          SELECT COUNT(*)::text AS total
          FROM audit_logs al
          WHERE ${conditions.join(' AND ')}
        `,
        params,
      );
      const total = Number(countRow?.total || 0);

      const resultParams = [...params, limit, offset];

      const rows = await BaseQuery.queryMany<any>(
        dbClient,
        `
          SELECT
            al.id,
            al.resource_id AS payment_id,
            al.action,
            al.user_id,
            COALESCE(
              NULLIF(TRIM(CONCAT_WS(' ', u.first_name, u.last_name)), ''),
              u.email,
              'Sistem'
            ) AS user_name,
            al.new_data AS details,
            al.created_at
          FROM audit_logs al
          LEFT JOIN users u ON u.id = al.user_id
          WHERE ${conditions.join(' AND ')}
          ORDER BY al.created_at ${sortDirection}
          LIMIT $${nextParam++}
          OFFSET $${nextParam++}
        `,
        resultParams,
      );

      const data = rows.map((row) => {
        let details: Record<string, any> | undefined;
        if (typeof row.details === 'string') {
          try {
            details = JSON.parse(row.details);
          } catch {
            details = undefined;
          }
        } else {
          details = row.details || undefined;
        }

        return {
          id: row.id,
          paymentId: row.payment_id ?? undefined,
          invoiceId: details?.invoiceId ?? undefined,
          action: row.action,
          userId: row.user_id ?? undefined,
          userName: row.user_name ?? undefined,
          details,
          createdAt: row.created_at ?? new Date(),
        } as PaymentAuditEntity;
      });

      return {
        data,
        total,
        page,
        limit,
      };
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async findUserIdsByRoles(
    roles: string[],
    client?: PoolClient,
  ): Promise<string[]> {
    if (!roles.length) return [];
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const rows = await BaseQuery.queryMany<{ id: string }>(
        dbClient,
        `
          SELECT id
          FROM users
          WHERE role = ANY($1::text[])
            AND is_active = true
        `,
        [roles],
      );
      return rows.map((row) => row.id);
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async findUserDisplayNameById(
    userId: string,
    client?: PoolClient,
  ): Promise<string | null> {
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const row = await BaseQuery.queryOne<{ name: string }>(
        dbClient,
        `
          SELECT
            COALESCE(
              NULLIF(TRIM(CONCAT_WS(' ', first_name, last_name)), ''),
              email
            ) AS name
          FROM users
          WHERE id = $1
        `,
        [userId],
      );
      return row?.name ?? null;
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  private async getPaymentsSchema(
    client: PoolClient,
  ): Promise<PaymentsSchemaSnapshot> {
    if (this.paymentsSchemaCache) {
      return this.paymentsSchemaCache;
    }

    try {
      const rows = await BaseQuery.queryMany<{ column_name: string }>(
        client,
        `
          SELECT column_name
          FROM information_schema.columns
          WHERE table_schema = 'public' AND table_name = 'payments'
        `,
        [],
      );
      const columns = new Set((rows || []).map((row) => row.column_name));

      this.paymentsSchemaCache = {
        hasPaymentDate: columns.has('payment_date'),
        hasReference: columns.has('reference'),
        hasNotes: columns.has('notes'),
        hasReceiptUrl: columns.has('receipt_url'),
        hasRecordedBy: columns.has('recorded_by'),
        hasCreatedAt: columns.has('created_at'),
      };
    } catch {
      // Keep current behavior in tests/runtime if schema lookup is unavailable.
      this.paymentsSchemaCache = {
        hasPaymentDate: true,
        hasReference: true,
        hasNotes: true,
        hasReceiptUrl: true,
        hasRecordedBy: true,
        hasCreatedAt: true,
      };
    }

    return this.paymentsSchemaCache;
  }
}

import { Controller, Get } from '@nestjs/common';
import { ApiOperation, ApiTags } from '@nestjs/swagger';
import { DatabasePool } from '../../../database/pool';
import { RedisService } from '../../../infrastructure/cache/redis.client';
import * as os from 'os';

@ApiTags('Health')
@Controller('health')
export class HealthController {
  constructor(
    private readonly dbPool: DatabasePool,
    private readonly redisService: RedisService,
  ) {}

  @ApiOperation({ summary: 'Check system health' })
  @Get()
  async check() {
    const dbStatus = await this.checkDatabase();
    const redisStatus = await this.checkRedis();

    const totalMem = os.totalmem();
    const freeMem = os.freemem();
    const usedMem = totalMem - freeMem;
    const memoryUsagePct = ((usedMem / totalMem) * 100).toFixed(2);

    return {
      status: dbStatus === 'up' && redisStatus === 'up' ? 'ok' : 'error',
      timestamp: new Date().toISOString(),
      services: {
        database: dbStatus,
        redis: redisStatus,
      },
      system: {
        memory: {
          total_mb: Math.round(totalMem / 1024 / 1024),
          free_mb: Math.round(freeMem / 1024 / 1024),
          usage_percent: `${memoryUsagePct}%`,
        },
        uptime_seconds: Math.round(process.uptime()),
      },
    };
  }

  private async checkDatabase(): Promise<'up' | 'down'> {
    try {
      const pool = this.dbPool.getPool();
      const client = await pool.connect();
      await client.query('SELECT 1');
      client.release();
      return 'up';
    } catch (error) {
      return 'down';
    }
  }

  private async checkRedis(): Promise<'up' | 'down'> {
    try {
      await this.redisService.get('health_check');
      return 'up';
    } catch (error) {
      return 'down';
    }
  }
}

import {
