@Injectable()
export class LandingService {
  private readonly logger = new Logger(LandingService.name);

  constructor(
    private readonly configService: ConfigService,
    private readonly clientsRepository: ClientsRepository,
    private readonly clientUsersRepository: ClientUsersRepository,
    private readonly contactRequestsRepository: LandingContactRequestsRepository,
    private readonly usersRepository: UsersRepository,
    @Inject(EMAIL_SERVICE) private readonly emailService: IEmailService,
  ) {}

  async submitContactMessage(dto: CreateContactMessageDto) {
    const normalizedPayload = {
      fullName: dto.fullName.trim(),
      email: dto.email.trim().toLowerCase(),
      phone: dto.phone?.trim(),
      company: dto.company?.trim(),
      subject: dto.subject.trim(),
      message: dto.message.trim(),
    };
    const storedRequest =
      await this.contactRequestsRepository.create(normalizedPayload);

    return {
      accepted: true,
      delivered: false,
      reason: 'pending_approval',
      requestId: storedRequest.id,
    };
  }

  async listContactRequests(query: ListContactRequestsQueryDto) {
    const page = query.page || 1;
    const limit = query.limit || 20;
    const status = query.status;
    const { data, total } = await this.contactRequestsRepository.findAll({
      page,
      limit,
      status,
      search: query.search?.trim() || undefined,
    });

    return {
      data,
      meta: {
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit),
      },
    };
  }

  async approveContactRequest(id: string, reviewerUserId: string) {
    const request = await this.contactRequestsRepository.findById(id);
    if (!request) {
      throw new HttpException(
        'Contact request not found',
        HttpStatus.NOT_FOUND,
      );
    }
    if (request.status !== 'PENDING') {
      throw new HttpException(
        'Only pending requests can be approved',
        HttpStatus.BAD_REQUEST,
      );
    }

    const existingClient = await this.clientsRepository.findByEmail(
      request.email,
    );
    let linkedClientId = existingClient?.id;

    if (existingClient) {
      if (!existingClient.isActive) {
        await this.clientsRepository.setActiveStatus(existingClient.id, true);
      }
    } else {
      const baseCompanyName =
        request.company?.trim() || `${request.fullName} Talebi`;
      let companyName = baseCompanyName;
      const existingCompany =
        await this.clientsRepository.findByCompanyName(companyName);
      if (existingCompany) {
        companyName = `${baseCompanyName} (${Date.now()})`;
      }

      const createdClient = await this.clientsRepository.create({
        companyName,
        contactPerson: request.fullName,
        email: request.email,
        phone: request.phone || undefined,
      });
      linkedClientId = createdClient.id;
      await this.clientsRepository.setActiveStatus(createdClient.id, true);
    }

    const approved = await this.contactRequestsRepository.markApproved(
      id,
      reviewerUserId,
      linkedClientId,
    );

    if (!approved) {
      throw new HttpException(
        'Approval operation failed',
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }

    try {
      const provisioned = await this.provisionClientPortalCredentials(
        linkedClientId,
        request.email,
      );

      await this.sendClientApprovalEmail({
        toEmail: request.email,
        contactName: request.fullName,
        companyName: request.company || undefined,
        temporaryPassword: provisioned.temporaryPassword,
        magicLink: provisioned.magicLink,
        expiresAt: provisioned.expiresAt,
      });
    } catch (error) {
      this.logger.error(
        `Contact request approved but portal onboarding email failed for ${request.email}: ${error instanceof Error ? error.message : String(error)}`,
      );
    }

    return approved;
  }

  async rejectContactRequest(
    id: string,
    reviewerUserId: string,
    reason?: string,
  ) {
    const request = await this.contactRequestsRepository.findById(id);
    if (!request) {
      throw new HttpException(
        'Contact request not found',
        HttpStatus.NOT_FOUND,
      );
    }
    if (request.status !== 'PENDING') {
      throw new HttpException(
        'Only pending requests can be rejected',
        HttpStatus.BAD_REQUEST,
      );
    }

    const rejected = await this.contactRequestsRepository.markRejected(
      id,
      reviewerUserId,
      reason?.trim() || undefined,
    );
    if (!rejected) {
      throw new HttpException(
        'Reject operation failed',
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }

    return rejected;
  }

  getCustomerPanelBootstrap() {
    return {
      routes: {
        login: '/api/v1/portal/login',
        dashboard: '/api/v1/portal/dashboard',
      },
      message: 'customer_panel_bootstrap_ready',
    };
  }

  async getTeamMembersByDepartment() {
    const departments =
      await this.usersRepository.findTeamMembersByDepartment();

    return {
      departments: departments.map((department) => ({
        department: department.department,
        members: department.members.map((member) => ({
          id: member.id,
          firstName: member.firstName,
          lastName: member.lastName,
          fullName: `${member.firstName} ${member.lastName}`.trim(),
          role: member.role,
          avatarUrl: member.avatarUrl,
          isActive: member.isActive,
        })),
      })),
    };
  }

  async getLandingContent() {
    const stored = await this.readLandingContentFile();
    return this.mergeLandingContent(stored);
  }

  async updateLandingContent(dto: LandingContentDto, updatedBy?: string) {
    const merged = this.mergeLandingContent(dto);
    const payload: LandingContent = {
      ...merged,
      meta: {
        updatedAt: new Date().toISOString(),
        updatedBy: updatedBy || null,
      },
    };
    await this.writeLandingContentFile(payload);
    return payload;
  }

  private async provisionClientPortalCredentials(
    clientId: string,
    email: string,
  ) {
    const normalizedEmail = email.trim().toLowerCase();
    const temporaryPassword = this.generateTemporaryPassword();
    const passwordHash = await bcrypt.hash(temporaryPassword, 10);
    const existingClientUser =
      await this.clientUsersRepository.findByEmail(normalizedEmail);

    let clientUserId = existingClientUser?.id;
    if (existingClientUser) {
      await this.clientUsersRepository.updatePasswordHash(
        existingClientUser.id,
        passwordHash,
        true,
      );
    } else {
      const createdClientUser = await this.clientUsersRepository.create({
        clientId,
        email: normalizedEmail,
        passwordHash,
        forcePasswordChange: true,
      });
      clientUserId = createdClientUser.id;
    }

    const token = randomBytes(32).toString('hex');
    const expiresAt = new Date();
    expiresAt.setHours(expiresAt.getHours() + 24);
    await this.clientUsersRepository.createAccessLink(
      clientUserId,
      token,
      expiresAt,
    );

    const portalBaseUrl = this.resolvePortalBaseUrl();
    const magicLink = `${portalBaseUrl}/portal/auth/verify?token=${token}&email=${encodeURIComponent(
      normalizedEmail,
    )}`;

    return {
      magicLink,
      temporaryPassword,
      expiresAt,
    };
  }

  private async sendClientApprovalEmail(payload: {
    toEmail: string;
    contactName: string;
    companyName?: string;
    temporaryPassword: string;
    magicLink: string;
    expiresAt: Date;
  }) {
    const senderEmail =
      this.configService.get<string>('app.adminEmail') || 'admin@trivexa.com';
    const templateId = this.configService.get<string>(
      'email.clientApprovalTemplateId',
    );

    await this.emailService.sendEmail({
      to: payload.toEmail,
      subject: 'Musteri portal erisiminiz olusturuldu',
      text: [
        `Merhaba ${payload.contactName},`,
        '',
        'Musteri kaydiniz onaylandi. Asagidaki bilgilerle portala giris yapabilirsiniz.',
        '',
        `Portal baglantisi: ${payload.magicLink}`,
        `E-posta: ${payload.toEmail}`,
        `Gecici sifre: ${payload.temporaryPassword}`,
        `Link gecerlilik suresi: ${payload.expiresAt.toISOString()}`,
        '',
        'Guvenlik nedeniyle ilk giriste sifrenizi degistirmeniz zorunludur.',
      ].join('\n'),
      templateId: templateId || undefined,
      variables: {
        from_name: 'Trivexa',
        from_email: senderEmail,
        to_name: payload.contactName,
        to_email: payload.toEmail,
        to: payload.toEmail,
        recipient: payload.toEmail,
        email: payload.toEmail,
        user_email: payload.toEmail,
        recipient_email: payload.toEmail,
        company_name: payload.companyName || '',
        portal_link: payload.magicLink,
        temporary_password: payload.temporaryPassword,
        expires_at: payload.expiresAt.toISOString(),
        subject: 'Musteri portal erisiminiz olusturuldu',
        message:
          'Musteri kaydiniz onaylandi. Bu e-postadaki baglanti ve gecici sifre ile portala giris yapabilirsiniz.',
      },
    });
  }

  private resolvePortalBaseUrl() {
    return (
      this.configService.get<string>('app.clientPortalBaseUrl') ||
      this.configService.get<string>('CLIENT_PORTAL_BASE_URL') ||
      'http://localhost:3001'
    ).replace(/\/+$/, '');
  }

  private generateTemporaryPassword(length = 12) {
    const alphabet =
      'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*';
    const bytes = randomBytes(length);
    let password = '';
    for (let i = 0; i < length; i += 1) {
      password += alphabet[bytes[i] % alphabet.length];
    }
    return password;
  }

  private mergeLandingContent(
    raw?: LandingContentInput | null,
  ): LandingContent {
    const payload = raw && typeof raw === 'object' ? raw : {};
    const hero = { ...DEFAULT_LANDING_CONTENT.hero, ...(payload.hero ?? {}) };
    const introParagraphs =
      Array.isArray(payload.intro?.paragraphs) &&
      payload.intro.paragraphs.length > 0
        ? payload.intro.paragraphs
        : DEFAULT_LANDING_CONTENT.intro.paragraphs;
    const introTickerTexts =
      Array.isArray(payload.intro?.tickerTexts) &&
      payload.intro.tickerTexts.length > 0
        ? payload.intro.tickerTexts
        : DEFAULT_LANDING_CONTENT.intro.tickerTexts;
    const intro = {
      ...DEFAULT_LANDING_CONTENT.intro,
      ...(payload.intro ?? {}),
      paragraphs: introParagraphs,
      tickerTexts: introTickerTexts,
    };
    const servicesItems =
      Array.isArray(payload.services?.items) &&
      payload.services.items.length > 0
        ? payload.services.items.map((item) => ({
            title: item.title ?? '',
            description: item.description ?? '',
          }))
        : DEFAULT_LANDING_CONTENT.services.items;
    const services = {
      ...DEFAULT_LANDING_CONTENT.services,
      ...(payload.services ?? {}),
      items: servicesItems,
    };
    const processSteps =
      Array.isArray(payload.process?.steps) && payload.process.steps.length > 0
        ? payload.process.steps.map((item) => ({
            title: item.title ?? '',
            description: item.description ?? '',
          }))
        : DEFAULT_LANDING_CONTENT.process.steps;
    const process = {
      ...DEFAULT_LANDING_CONTENT.process,
      ...(payload.process ?? {}),
      steps: processSteps,
    };
    const impactStats =
      Array.isArray(payload.impact?.stats) && payload.impact.stats.length > 0
        ? payload.impact.stats.map((item) => ({
            value: item.value ?? '',
            label: item.label ?? '',
          }))
        : DEFAULT_LANDING_CONTENT.impact.stats;
    const impact = {
      ...DEFAULT_LANDING_CONTENT.impact,
      ...(payload.impact ?? {}),
      stats: impactStats,
    };
    const contact = {
      ...DEFAULT_LANDING_CONTENT.contact,
      ...(payload.contact ?? {}),
    };

    return {
      hero,
      intro,
      services,
      process,
      impact,
      contact,
      meta: payload.meta ?? undefined,
    };
  }

  private resolveLandingContentPath() {
    return join(process.cwd(), 'storage', 'landing-content.json');
  }

  private async readLandingContentFile(): Promise<LandingContent | null> {
    const filePath = this.resolveLandingContentPath();
    try {
      const raw = await fs.readFile(filePath, 'utf8');
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed === 'object') {
        return parsed as LandingContent;
      }
    } catch {
      return null;
    }
    return null;
  }

  private async writeLandingContentFile(payload: LandingContent) {
    const filePath = this.resolveLandingContentPath();
    const dir = join(process.cwd(), 'storage');
    await fs.mkdir(dir, { recursive: true });
    await fs.writeFile(filePath, JSON.stringify(payload, null, 2), 'utf8');
  }
}

import { Injectable } from '@nestjs/common';
import { PoolClient } from 'pg';
import { v4 as uuidv4 } from 'uuid';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';

export type LandingContactRequestStatus = 'PENDING' | 'APPROVED' | 'REJECTED';

export interface LandingContactRequestEntity {
  id: string;
  fullName: string;
  email: string;
  phone?: string | null;
  company?: string | null;
  subject: string;
  message: string;
  status: LandingContactRequestStatus;
  source: string;
  reason?: string | null;
  reviewedBy?: string | null;
  reviewedAt?: string | null;
  linkedClientId?: string | null;
  createdAt: string;
  updatedAt: string;
}

@Injectable()
export class LandingContactRequestsRepository {
  private schemaEnsured = false;

  constructor(private readonly db: DatabasePool) {}

  private mapRow(row: any): LandingContactRequestEntity {
    return {
      id: row.id,
      fullName: row.full_name,
      email: row.email,
      phone: row.phone ?? null,
      company: row.company ?? null,
      subject: row.subject,
      message: row.message,
      status: row.status,
      source: row.source,
      reason: row.reason ?? null,
      reviewedBy: row.reviewed_by ?? null,
      reviewedAt: row.reviewed_at ?? null,
      linkedClientId: row.linked_client_id ?? null,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }

  private async ensureSchema(client: PoolClient): Promise<void> {
    if (this.schemaEnsured) {
      return;
    }

    await BaseQuery.execute(
      client,
      `
      CREATE TABLE IF NOT EXISTS landing_contact_requests (
        id UUID PRIMARY KEY,
        full_name VARCHAR(120) NOT NULL,
        email VARCHAR(160) NOT NULL,
        phone VARCHAR(32),
        company VARCHAR(120),
        subject VARCHAR(160) NOT NULL,
        message TEXT NOT NULL,
        status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
        source VARCHAR(40) NOT NULL DEFAULT 'LANDING',
        reason TEXT,
        reviewed_by UUID,
        reviewed_at TIMESTAMPTZ,
        linked_client_id UUID,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      );
      CREATE INDEX IF NOT EXISTS idx_landing_contact_requests_status_created_at
        ON landing_contact_requests(status, created_at DESC);
      CREATE INDEX IF NOT EXISTS idx_landing_contact_requests_email
        ON landing_contact_requests(email);
      `,
    );

    this.schemaEnsured = true;
  }

  async create(payload: {
    fullName: string;
    email: string;
    phone?: string;
    company?: string;
    subject: string;
    message: string;
    source?: string;
  }): Promise<LandingContactRequestEntity> {
    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const row = await BaseQuery.queryOne<any>(
        client,
        `
        INSERT INTO landing_contact_requests (
          id, full_name, email, phone, company, subject, message, source
        )
        VALUES ($1,$2,$3,$4,$5,$6,$7,$8)
        RETURNING *
        `,
        [
          uuidv4(),
          payload.fullName,
          payload.email,
          payload.phone || null,
          payload.company || null,
          payload.subject,
          payload.message,
          payload.source || 'LANDING',
        ],
      );

      return this.mapRow(row);
    } finally {
      client.release();
    }
  }

  async findById(id: string): Promise<LandingContactRequestEntity | null> {
    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const row = await BaseQuery.queryOne<any>(
        client,
        `SELECT * FROM landing_contact_requests WHERE id = $1`,
        [id],
      );
      return row ? this.mapRow(row) : null;
    } finally {
      client.release();
    }
  }

  async findAll(query: {
    page: number;
    limit: number;
    status?: LandingContactRequestStatus;
    search?: string;
  }): Promise<{ data: LandingContactRequestEntity[]; total: number }> {
    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);

      const conditions: string[] = [];
      const params: any[] = [];
      let paramIndex = 1;

      if (query.status) {
        conditions.push(`status = $${paramIndex++}`);
        params.push(query.status);
      }

      if (query.search) {
        conditions.push(
          `(LOWER(full_name) LIKE $${paramIndex} OR LOWER(email) LIKE $${paramIndex} OR LOWER(company) LIKE $${paramIndex})`,
        );
        params.push(`%${query.search.toLowerCase()}%`);
        paramIndex += 1;
      }

      const whereClause = conditions.length
        ? `WHERE ${conditions.join(' AND ')}`
        : '';
      const countRow = await BaseQuery.queryOne<{ count: string }>(
        client,
        `SELECT COUNT(*)::text as count FROM landing_contact_requests ${whereClause}`,
        params,
      );

      params.push(query.limit, (query.page - 1) * query.limit);

      const rows = await BaseQuery.queryMany<any>(
        client,
        `
        SELECT * FROM landing_contact_requests
        ${whereClause}
        ORDER BY created_at DESC
        LIMIT $${paramIndex++} OFFSET $${paramIndex++}
        `,
        params,
      );

      return {
        data: rows.map((row) => this.mapRow(row)),
        total: Number(countRow?.count || 0),
      };
    } finally {
      client.release();
    }
  }

  async markApproved(
    id: string,
    reviewerId: string,
    linkedClientId: string,
  ): Promise<LandingContactRequestEntity | null> {
    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const row = await BaseQuery.queryOne<any>(
        client,
        `
        UPDATE landing_contact_requests
        SET status = 'APPROVED',
            reviewed_by = $2,
            reviewed_at = NOW(),
            linked_client_id = $3,
            reason = NULL,
            updated_at = NOW()
        WHERE id = $1
        RETURNING *
        `,
        [id, reviewerId, linkedClientId],
      );
      return row ? this.mapRow(row) : null;
    } finally {
      client.release();
    }
  }

  async markRejected(
    id: string,
    reviewerId: string,
    reason?: string,
  ): Promise<LandingContactRequestEntity | null> {
    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const row = await BaseQuery.queryOne<any>(
        client,
        `
        UPDATE landing_contact_requests
        SET status = 'REJECTED',
            reviewed_by = $2,
            reviewed_at = NOW(),
            reason = $3,
            updated_at = NOW()
        WHERE id = $1
        RETURNING *
        `,
        [id, reviewerId, reason || null],
      );
      return row ? this.mapRow(row) : null;
    } finally {
      client.release();
    }
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { LeaveRequestsRepository } from '../infrastructure/leave-requests.repository';
import { LeaveRequestsQueryDto } from '../api/dto/leave-requests.query.dto';
import { UpdateLeaveStatusDto } from '../api/dto/update-leave-status.dto';
import { CreateLeaveRequestDto } from '../api/dto/create-leave-request.dto';
import { LeaveStatus } from '../domain/leave.enums';

@Injectable()
export class LeaveRequestsService {
  constructor(private readonly leaveRepo: LeaveRequestsRepository) {}

  async findAll(query: LeaveRequestsQueryDto) {
    const data = await this.leaveRepo.findAll({
      status: query.status,
      type: query.type,
      department: query.department,
      search: query.search?.trim() || undefined,
    });
    return { data };
  }

  async create(dto: CreateLeaveRequestDto, user: any) {
    const userId = dto.userId ?? user?.userId;
    if (!userId) {
      throw new NotFoundException('Kullanici bilgisi bulunamadi.');
    }

    const created = await this.leaveRepo.create({
      userId,
      department: dto.department ?? user?.department ?? null,
      type: dto.type,
      status: LeaveStatus.PENDING,
      startDate: dto.startDate,
      endDate: dto.endDate,
      durationDays: dto.durationDays,
      reason: dto.reason ?? null,
    });

    if (!created) {
      throw new NotFoundException('Izin kaydi olusturulamadi.');
    }

    return { data: created };
  }

  async updateStatus(id: string, dto: UpdateLeaveStatusDto, user: any) {
    const status = dto.status;
    const approvedAt = status === LeaveStatus.PENDING ? null : new Date();

    const updated = await this.leaveRepo.updateStatus({
      id,
      status,
      approvedBy: user?.userId ?? null,
      approvedAt,
    });

    if (!updated) {
      throw new NotFoundException('Izin kaydi bulunamadi.');
    }

    return { data: updated };
  }
}

import { LeaveStatus, LeaveType } from './leave.enums';

const TYPE_NORMALIZATION: Record<string, LeaveType> = {
  YILLIK: LeaveType.YILLIK,
  YILLIK_IZIN: LeaveType.YILLIK,
  ANNUAL: LeaveType.YILLIK,
  YEARLY: LeaveType.YILLIK,
  MAZERET: LeaveType.MAZERET,
  RAPOR: LeaveType.RAPOR,
  UCRETSIZ: LeaveType.UCRETSIZ,
  DIGER: LeaveType.DIGER,
};

function normalizeLeaveType(value: unknown): LeaveType {
  const key = String(value ?? '')
    .trim()
    .toUpperCase();
  return TYPE_NORMALIZATION[key] ?? LeaveType.DIGER;
}

export interface LeaveRequestEntity {
  id: string;
  userId: string;
  employeeName: string;
  employeeEmail?: string | null;
  department: string | null;
  type: LeaveType;
  status: LeaveStatus;
  startDate: string;
  endDate: string;
  durationDays: number;
  reason?: string | null;
  approvedBy?: string | null;
  approvedAt?: string | null;
  createdAt: string;
  updatedAt: string;
}

export class LeaveRequestModel {
  static fromRow(row: any): LeaveRequestEntity {
    const employeeName = [row.first_name, row.last_name]
      .filter(Boolean)
      .join(' ')
      .trim();
    return {
      id: row.id,
      userId: row.user_id,
      employeeName: employeeName || row.employee_name || 'Bilinmeyen',
      employeeEmail: row.email ?? row.employee_email ?? null,
      department: row.department ?? null,
      type: normalizeLeaveType(row.type),
      status: row.status,
      startDate: row.start_date,
      endDate: row.end_date,
      durationDays: row.duration_days,
      reason: row.reason ?? null,
      approvedBy: row.approved_by ?? null,
      approvedAt: row.approved_at ?? null,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }
}

import { Injectable } from '@nestjs/common';
import { PoolClient } from 'pg';
import { randomUUID } from 'crypto';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';
import {
  LeaveRequestEntity,
  LeaveRequestModel,
} from '../domain/leave-request.entity';
import { LeaveRequestsSql } from './sql/leave-requests.sql';
import { LeaveStatus, LeaveType } from '../domain/leave.enums';

@Injectable()
export class LeaveRequestsRepository {
  constructor(private readonly db: DatabasePool) {}
  private schemaEnsured = false;

  private async ensureSchema(client: PoolClient): Promise<void> {
    if (this.schemaEnsured) return;

    await client.query(`
      CREATE TABLE IF NOT EXISTS leave_requests (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        department TEXT,
        type TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'PENDING',
        start_date DATE NOT NULL,
        end_date DATE NOT NULL,
        duration_days INTEGER NOT NULL DEFAULT 1,
        reason TEXT,
        approved_by UUID REFERENCES users(id),
        approved_at TIMESTAMPTZ,
        created_at TIMESTAMPTZ DEFAULT now(),
        updated_at TIMESTAMPTZ DEFAULT now()
      );

      CREATE INDEX IF NOT EXISTS idx_leave_requests_user_id ON leave_requests(user_id);
      CREATE INDEX IF NOT EXISTS idx_leave_requests_status ON leave_requests(status);
      CREATE INDEX IF NOT EXISTS idx_leave_requests_start_date ON leave_requests(start_date);
    `);

    this.schemaEnsured = true;
  }

  async findAll(filters: {
    status?: LeaveStatus;
    type?: LeaveType;
    department?: string;
    search?: string;
  }): Promise<LeaveRequestEntity[]> {
    let sql = LeaveRequestsSql.FIND_ALL_BASE;
    const params: any[] = [];

    if (filters.status) {
      params.push(filters.status);
      sql += ` AND lr.status = $${params.length}`;
    }
    if (filters.type) {
      if (filters.type === LeaveType.YILLIK) {
        params.push(LeaveType.YILLIK, 'YILLIK_IZIN', 'ANNUAL', 'YEARLY');
        const firstIndex = params.length - 3;
        sql += ` AND lr.type IN ($${firstIndex}, $${firstIndex + 1}, $${firstIndex + 2}, $${firstIndex + 3})`;
      } else {
        params.push(filters.type);
        sql += ` AND lr.type = $${params.length}`;
      }
    }
    if (filters.department) {
      params.push(filters.department);
      sql += ` AND COALESCE(lr.department, u.department) = $${params.length}`;
    }
    if (filters.search) {
      params.push(`%${filters.search}%`);
      sql += ` AND (
        u.first_name ILIKE $${params.length}
        OR u.last_name ILIKE $${params.length}
        OR u.email ILIKE $${params.length}
        OR COALESCE(lr.department, u.department) ILIKE $${params.length}
      )`;
    }

    sql += LeaveRequestsSql.FIND_ALL_ORDER;

    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const rows = await BaseQuery.queryMany<any>(client, sql, params);
      return rows.map((row) => LeaveRequestModel.fromRow(row));
    } finally {
      client.release();
    }
  }

  async findById(id: string): Promise<LeaveRequestEntity | null> {
    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const row = await BaseQuery.queryOne<any>(
        client,
        LeaveRequestsSql.FIND_BY_ID,
        [id],
      );
      return row ? LeaveRequestModel.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async create(payload: {
    userId: string;
    department?: string | null;
    type: LeaveType;
    status?: LeaveStatus;
    startDate: string;
    endDate: string;
    durationDays: number;
    reason?: string | null;
  }): Promise<LeaveRequestEntity | null> {
    const params = [
      randomUUID(),
      payload.userId,
      payload.department ?? null,
      payload.type,
      payload.status ?? LeaveStatus.PENDING,
      payload.startDate,
      payload.endDate,
      payload.durationDays,
      payload.reason ?? null,
    ];

    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const row = await BaseQuery.queryOne<any>(
        client,
        LeaveRequestsSql.CREATE,
        params,
      );
      if (!row) return null;
      const withUser = await BaseQuery.queryOne<any>(
        client,
        LeaveRequestsSql.FIND_BY_ID,
        [row.id],
      );
      return withUser ? LeaveRequestModel.fromRow(withUser) : null;
    } finally {
      client.release();
    }
  }

  async updateStatus(payload: {
    id: string;
    status: LeaveStatus;
    approvedBy?: string | null;
    approvedAt?: Date | null;
  }): Promise<LeaveRequestEntity | null> {
    const params = [
      payload.id,
      payload.status,
      payload.approvedBy ?? null,
      payload.approvedAt ?? null,
    ];

    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const row = await BaseQuery.queryOne<any>(
        client,
        LeaveRequestsSql.UPDATE_STATUS,
        params,
      );
      if (!row) return null;
      const withUser = await BaseQuery.queryOne<any>(
        client,
        LeaveRequestsSql.FIND_BY_ID,
        [row.id],
      );
      return withUser ? LeaveRequestModel.fromRow(withUser) : null;
    } finally {
      client.release();
    }
  }
}

