import { Injectable } from '@nestjs/common';
import { PoolClient } from 'pg';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';
import { Meeting, MeetingEntity } from '../domain/meeting.entity';
import { MeetingsSql } from './sql/meetings.sql';

export interface MeetingAccessContext {
  userId: string;
  role: string;
  department?: string | null;
  canViewAll: boolean;
  isManager: boolean;
}

@Injectable()
export class MeetingsRepository {
  constructor(private readonly db: DatabasePool) {}
  private schemaEnsured = false;

  private async ensureSchema(client: PoolClient): Promise<void> {
    if (this.schemaEnsured) return;

    await client.query(`
      DO $$
      BEGIN
        IF EXISTS (
          SELECT 1 FROM information_schema.tables
          WHERE table_schema = 'public' AND table_name = 'meetings'
        ) THEN
          ALTER TABLE meetings
            ADD COLUMN IF NOT EXISTS summary TEXT,
            ADD COLUMN IF NOT EXISTS audience_type TEXT NOT NULL DEFAULT 'PERSONAL',
            ADD COLUMN IF NOT EXISTS department TEXT;

          CREATE INDEX IF NOT EXISTS idx_meetings_audience_type ON meetings(audience_type);
          CREATE INDEX IF NOT EXISTS idx_meetings_department ON meetings(department);
          CREATE INDEX IF NOT EXISTS idx_meetings_project_id ON meetings(project_id);
          CREATE INDEX IF NOT EXISTS idx_meetings_date ON meetings(date);
        END IF;
      END
      $$;
    `);

    this.schemaEnsured = true;
  }

  private applyAccessPredicate(
    baseSql: string,
    params: any[],
    access?: MeetingAccessContext,
  ): string {
    if (!access || access.canViewAll) return baseSql;

    const userIdParam = params.push(access.userId);
    const roleParam = params.push(String(access.role ?? '').toUpperCase());
    const departmentParam = params.push(access.department ?? '');
    const isManagerParam = params.push(Boolean(access.isManager));

    return `${baseSql}
      AND (
        m.organizer_id = $${userIdParam}
        OR (
          m.audience_type = 'PROJECT'
          AND m.project_id IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM project_members pm
            WHERE pm.project_id = m.project_id
              AND pm.user_id = $${userIdParam}
          )
        )
        OR (
          m.audience_type = 'DEPARTMENT'
          AND COALESCE($${departmentParam}, '') <> ''
          AND UPPER(m.department) = UPPER($${departmentParam})
        )
        OR (
          m.audience_type = 'ALL_PERSONNEL'
          AND $${roleParam} <> 'CLIENT'
        )
        OR (
          m.audience_type = 'MANAGERS'
          AND $${isManagerParam} = TRUE
        )
      )
    `;
  }

  async create(
    meeting: MeetingEntity,
    client?: PoolClient,
  ): Promise<MeetingEntity> {
    const sql = MeetingsSql.CREATE;
    const params = [
      meeting.clientId,
      meeting.projectId,
      meeting.audienceType,
      meeting.department,
      meeting.title,
      meeting.date,
      meeting.durationMinutes,
      meeting.link,
      meeting.notes,
      meeting.summary,
      meeting.organizerId,
    ];

    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      await this.ensureSchema(dbClient);
      const row = await BaseQuery.queryOne<any>(dbClient, sql, params);
      return Meeting.fromRow(row);
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async findAll(
    filters: {
      clientId?: string;
      projectId?: string;
    },
    access?: MeetingAccessContext,
  ): Promise<MeetingEntity[]> {
    let sql = MeetingsSql.FIND_ALL_BASE;
    const params: any[] = [];

    if (filters.clientId) {
      params.push(filters.clientId);
      sql += ` AND m.client_id = $${params.length}`;
    }
    if (filters.projectId) {
      params.push(filters.projectId);
      sql += ` AND m.project_id = $${params.length}`;
    }

    sql = this.applyAccessPredicate(sql, params, access);
    sql += MeetingsSql.FIND_ALL_ORDER;

    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const rows = await BaseQuery.queryMany<any>(client, sql, params);
      return rows.map((row) => Meeting.fromRow(row));
    } finally {
      client.release();
    }
  }

  async findById(id: string): Promise<MeetingEntity | null> {
    const sql = MeetingsSql.FIND_BY_ID;
    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const row = await BaseQuery.queryOne<any>(client, sql, [id]);
      return row ? Meeting.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async findByIdForUser(
    id: string,
    access: MeetingAccessContext,
  ): Promise<MeetingEntity | null> {
    let sql = `SELECT * FROM meetings m WHERE m.id = $1`;
    const params: any[] = [id];
    sql = this.applyAccessPredicate(sql, params, access);

    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const row = await BaseQuery.queryOne<any>(client, sql, params);
      return row ? Meeting.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async update(
    id: string,
    data: Partial<{
      title: string;
      date: string;
      durationMinutes: number;
      clientId: string;
      projectId: string | null;
      audienceType: string;
      department: string | null;
      link: string;
      notes: string;
      summary: string;
    }>,
  ): Promise<MeetingEntity | null> {
    const setClauses: string[] = [];
    const params: any[] = [id];
    let paramIndex = 2;

    const fieldMap: Record<string, string> = {
      title: 'title',
      date: 'date',
      durationMinutes: 'duration_minutes',
      clientId: 'client_id',
      projectId: 'project_id',
      audienceType: 'audience_type',
      department: 'department',
      link: 'link',
      notes: 'notes',
      summary: 'summary',
    };

    const dataRecord = data as Record<string, unknown>;
    for (const [key, column] of Object.entries(fieldMap)) {
      if (dataRecord[key] !== undefined) {
        setClauses.push(`${column} = $${paramIndex++}`);
        params.push(dataRecord[key]);
      }
    }

    if (setClauses.length === 0) return this.findById(id);

    const sql = `UPDATE meetings SET ${setClauses.join(', ')}, updated_at = NOW() WHERE id = $1 RETURNING *`;
    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const row = await BaseQuery.queryOne<any>(client, sql, params);
      return row ? Meeting.fromRow(row) : null;
    } finally {
      client.release();
    }
  }
}

import { ApiPropertyOptional } from '@nestjs/swagger';
import { Type, Transform } from 'class-transformer';
import { IsBoolean, IsInt, IsOptional, IsString, Min } from 'class-validator';

export class ListNotificationsQueryDto {
  @ApiPropertyOptional({ minimum: 1, default: 1 })
  @IsOptional()
  @Transform(({ value }) => parseInt(value, 10))
  @IsInt()
  @Min(1)
  page?: number = 1;

  @ApiPropertyOptional({ minimum: 1, default: 20 })
  @IsOptional()
  @Transform(({ value }) => parseInt(value, 10))
  @IsInt()
  @Min(1)
  limit?: number = 20;

  @ApiPropertyOptional({
    example: false,
    description: 'Filter by read status',
  })
  @IsOptional()
  @IsBoolean()
  @Type(() => Boolean)
  isRead?: boolean;

  @ApiPropertyOptional({
    example: 'SYSTEM',
    description: 'Notification type',
  })
  @IsOptional()
  @IsString()
  type?: string;
}

import {
  Controller,
  Get,
  Param,
  Patch,
  Query,
  UseGuards,
  Post,
  Body,
} from '@nestjs/common';
import { NotificationsRepository } from '../infrastructure/notifications.repository';
import { MarkReadUseCase } from '../application/usecases/mark-read.usecase';
import { MarkAllReadUseCase } from '../application/usecases/mark-all-read.usecase';
import { SendEmailUseCase } from '../application/usecases/send-email.usecase';
import { JwtAuthGuard } from '../../../common/guards/jwt-auth.guard';
import { CurrentUser } from '../../../common/decorators/current-user.decorator';
import { ListNotificationsQueryDto } from './dto/list-notifications.query';
import { SendEmailDto } from './dto/send-email.dto';
import {
  ApiTags,
  ApiBearerAuth,
  ApiOperation,
  ApiResponse,
} from '@nestjs/swagger';
import {
  NotificationsListResponseDto,
  UnreadCountResponseDto,
} from './dto/response/notifications-response.dto';
import { StandardResponseDto } from '../../../shared/dto/api-response.dto';

@ApiTags('Notifications')
@ApiBearerAuth('access-token')
@Controller('notifications')
@UseGuards(JwtAuthGuard)
export class NotificationsController {
  constructor(
    private readonly notificationsRepo: NotificationsRepository,
    private readonly markReadUseCase: MarkReadUseCase,
    private readonly markAllReadUseCase: MarkAllReadUseCase,
    private readonly sendEmailUseCase: SendEmailUseCase,
  ) {}

  @ApiOperation({ summary: 'Send an email notification' })
  @ApiResponse({
    status: 201,
    description: 'Email queued/sent.',
    type: StandardResponseDto,
  })
  @Post('email')
  async sendEmail(@Body() dto: SendEmailDto) {
    await this.sendEmailUseCase.execute(
      dto.to,
      dto.subject,
      dto.content,
      dto.isHtml,
    );
    return { success: true, message: 'Email queued/sent' };
  }

  @ApiOperation({ summary: 'Get current user notifications' })
  @ApiResponse({
    status: 200,
    description: 'Return notifications list page.',
    type: NotificationsListResponseDto,
  })
  @Get()
  async getNotifications(
    @CurrentUser() user: any,
    @Query() query: ListNotificationsQueryDto,
  ) {
    return this.notificationsRepo.findByUser(user.userId, query);
  }

  @ApiOperation({ summary: 'Get unread notification count' })
  @ApiResponse({
    status: 200,
    description: 'Return unread count.',
    type: UnreadCountResponseDto,
  })
  @Get('unread-count')
  async getUnreadCount(@CurrentUser() user: any) {
    return this.notificationsRepo.countUnread(user.userId);
  }

  @ApiOperation({ summary: 'Mark single notification as read' })
  @ApiResponse({
    status: 200,
    description: 'Notification marked read.',
    type: StandardResponseDto,
  })
  @Patch(':id/read')
  async markAsRead(@Param('id') id: string) {
    // In a real scenario, check if notification belongs to user
    const success = await this.markReadUseCase.execute(id);
    return { success };
  }

  @ApiOperation({ summary: 'Mark all notifications as read for current user' })
  @ApiResponse({
    status: 200,
    description: 'All notifications marked read.',
    type: StandardResponseDto,
  })
  @Patch('read-all')
  async markAllAsRead(@CurrentUser() user: any) {
    await this.markAllReadUseCase.execute(user.userId);
    return { success: true };
  }
}

