import { Injectable } from '@nestjs/common';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';
import { Notification } from '../domain/notification.entity';
import { ListNotificationsQueryDto } from '../api/dto/list-notifications.query';
import { PageDto } from '../../../shared/dto/page.dto';
import { PageMetaDto } from '../../../shared/dto/page-meta.dto';
import { NotificationsSql } from './sql/notifications.sql';

@Injectable()
export class NotificationsRepository {
  constructor(private readonly dbPool: DatabasePool) {}

  async create(data: {
    userId: string;
    type: string;
    title: string;
    message: string;
    metadata?: Record<string, any>;
  }): Promise<Notification> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(client, NotificationsSql.create, [
        data.userId,
        data.type,
        data.title,
        data.message,
        data.metadata || {},
      ]);
      return new Notification(this.mapRow(row));
    } finally {
      client.release();
    }
  }

  async findByUser(
    userId: string,
    query: ListNotificationsQueryDto,
  ): Promise<PageDto<Notification>> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const conditions: string[] = [`user_id = $1`];
      const params: any[] = [userId];
      let idx = 2;

      if (query.isRead !== undefined) {
        conditions.push(`is_read = $${idx++}`);
        params.push(query.isRead);
      }
      if (query.type) {
        conditions.push(`type = $${idx++}`);
        params.push(query.type);
      }

      const where = `WHERE ${conditions.join(' AND ')}`;
      const page = query.page || 1;
      const limit = query.limit || 20;
      const offset = (page - 1) * limit;

      const [rows, countRow] = await Promise.all([
        BaseQuery.queryMany(
          client,
          `${NotificationsSql.findByUserBase}
                   ${where}
                   ORDER BY created_at DESC
                   LIMIT $${idx} OFFSET $${idx + 1}`,
          [...params, limit, offset],
        ),
        BaseQuery.queryOne<{ total: string }>(
          client,
          `SELECT COUNT(*) as total FROM notifications ${where}`,
          params,
        ),
      ]);

      const totalCount = parseInt(countRow?.total || '0', 10);
      const notifications = rows.map(
        (row) => new Notification(this.mapRow(row)),
      );
      const pageMeta = new PageMetaDto({
        page,
        limit,
        itemCount: totalCount,
      });

      return new PageDto(notifications, pageMeta);
    } finally {
      client.release();
    }
  }

  async markAsRead(id: string): Promise<boolean> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const count = await BaseQuery.execute(
        client,
        NotificationsSql.markAsRead,
        [id],
      );
      return count > 0;
    } finally {
      client.release();
    }
  }

  async markAllAsRead(userId: string): Promise<void> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      await BaseQuery.execute(client, NotificationsSql.markAllAsRead, [userId]);
    } finally {
      client.release();
    }
  }

  async countUnread(userId: string): Promise<number> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne<{ count: string }>(
        client,
        NotificationsSql.countUnread,
        [userId],
      );
      return parseInt(row?.count || '0', 10);
    } finally {
      client.release();
    }
  }

  private mapRow(row: any): Partial<Notification> {
    return {
      id: row.id,
      userId: row.user_id,
      type: row.type,
      title: row.title,
      message: row.message,
      isRead: row.is_read,
      metadata: row.metadata,
      createdAt: row.created_at,
    };
  }
}

import {
  OnGatewayConnection,
  OnGatewayDisconnect,
  WebSocketGateway,
  WebSocketServer,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Logger } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';

@WebSocketGateway({
  namespace: 'notifications',
  cors: {
    origin: '*', // Adjust in production
  },
})
export class NotificationsGateway
  implements OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer()
  server: Server;

  private readonly logger = new Logger(NotificationsGateway.name);

  constructor(
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
  ) {}

  async handleConnection(client: Socket) {
    try {
      const token = this.extractToken(client);
      if (!token) {
        this.logger.warn(`Client ${client.id} has no token`);
        client.disconnect();
        return;
      }

      const accessSecret =
        this.configService.get<string>('jwt.accessSecret') ||
        this.configService.get<string>('JWT_ACCESS_SECRET') ||
        this.configService.get<string>('jwt.secret');

      if (!accessSecret) {
        this.logger.error(
          'JWT access secret is not configured for notifications gateway',
        );
        client.disconnect();
        return;
      }

      const payload = this.jwtService.verify(token, {
        secret: accessSecret,
      });

      const userId = payload.sub;
      client.join(userId); // Join room named by userId
      this.logger.log(`Client ${client.id} connected as User ${userId}`);
    } catch (err) {
      this.logger.error(
        `Connection error for client ${client.id}: ${err.message}`,
      );
      client.disconnect();
    }
  }

  handleDisconnect(client: Socket) {
    this.logger.log(`Client ${client.id} disconnected`);
  }

  notifyUser(userId: string, payload: any) {
    this.server.to(userId).emit('notification', payload);
  }

  private extractToken(client: Socket): string | undefined {
    const authHeader = client.handshake.headers.authorization;
    if (authHeader && authHeader.split(' ')[0] === 'Bearer') {
      return authHeader.split(' ')[1];
    }
    const queryToken = client.handshake.query.token;
    if (typeof queryToken === 'string') {
      return queryToken;
    }
    return undefined;
  }
}

import { BadRequestException, Injectable } from '@nestjs/common';
import { PerformanceRepository } from '../infrastructure/performance.repository';
import { PerformanceQueryDto } from '../api/dto/performance-query.dto';
import { UpsertPerformanceDto } from '../api/dto/upsert-performance.dto';

@Injectable()
export class PerformanceService {
  constructor(private readonly performanceRepo: PerformanceRepository) {}

  async findAll(query: PerformanceQueryDto) {
    const data = await this.performanceRepo.findAll({
      userId: query.userId,
      startDate: query.startDate,
      endDate: query.endDate,
    });
    return { data };
  }

  async upsert(dto: UpsertPerformanceDto, user: any) {
    const start = new Date(dto.periodStart);
    const end = new Date(dto.periodEnd);
    if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) {
      throw new BadRequestException('Tarih araligi gecersiz.');
    }
    if (end < start) {
      throw new BadRequestException('Bitis tarihi baslangictan once olamaz.');
    }

    const created = await this.performanceRepo.upsert({
      userId: dto.userId,
      periodStart: dto.periodStart,
      periodEnd: dto.periodEnd,
      score: dto.score,
      bonusAmount: dto.bonusAmount,
      notes: dto.notes ?? null,
      createdBy: user?.userId ?? null,
    });

    if (!created) {
      throw new BadRequestException('Performans kaydi olusturulamadi.');
    }

    return { data: created };
  }
}

export interface PerformanceReviewEntity {
  id: string;
  userId: string;
  userName: string;
  userEmail?: string | null;
  periodStart: string;
  periodEnd: string;
  score: number;
  bonusAmount: number;
  notes?: string | null;
  createdBy?: string | null;
  createdAt: string;
  updatedAt: string;
}

function toNumber(value: unknown, fallback: number = 0): number {
  const parsed = typeof value === 'number' ? value : Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

export class PerformanceReviewModel {
  static fromRow(row: any): PerformanceReviewEntity {
    const firstName = row.first_name ?? row.user_first_name ?? '';
    const lastName = row.last_name ?? row.user_last_name ?? '';
    const userName =
      `${firstName} ${lastName}`.trim() || row.user_name || 'Bilinmeyen';
    return {
      id: row.id,
      userId: row.user_id,
      userName,
      userEmail: row.email ?? row.user_email ?? null,
      periodStart: row.period_start,
      periodEnd: row.period_end,
      score: toNumber(row.score, 0),
      bonusAmount: toNumber(row.bonus_amount, 0),
      notes: row.notes ?? null,
      createdBy: row.created_by ?? null,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }
}

import { Injectable } from '@nestjs/common';
import { PoolClient } from 'pg';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';
import {
  PerformanceReviewEntity,
  PerformanceReviewModel,
} from '../domain/performance.entity';
import { PerformanceSql } from './sql/performance.sql';

@Injectable()
export class PerformanceRepository {
  constructor(private readonly db: DatabasePool) {}
  private schemaEnsured = false;

  private async ensureSchema(client: PoolClient): Promise<void> {
    if (this.schemaEnsured) return;

    await client.query(`
      CREATE TABLE IF NOT EXISTS performance_reviews (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        period_start DATE NOT NULL,
        period_end DATE NOT NULL,
        score NUMERIC(5,2) NOT NULL DEFAULT 0,
        bonus_amount NUMERIC(12,2) NOT NULL DEFAULT 0,
        notes TEXT,
        created_by UUID REFERENCES users(id),
        created_at TIMESTAMPTZ DEFAULT now(),
        updated_at TIMESTAMPTZ DEFAULT now(),
        UNIQUE (user_id, period_start, period_end)
      );

      CREATE INDEX IF NOT EXISTS idx_performance_user_id ON performance_reviews(user_id);
      CREATE INDEX IF NOT EXISTS idx_performance_period_start ON performance_reviews(period_start);
    `);

    this.schemaEnsured = true;
  }

  async findAll(filters: {
    userId?: string;
    startDate?: string;
    endDate?: string;
  }): Promise<PerformanceReviewEntity[]> {
    let sql = PerformanceSql.FIND_ALL_BASE;
    const params: any[] = [];

    if (filters.userId) {
      params.push(filters.userId);
      sql += ` AND pr.user_id = $${params.length}`;
    }

    if (filters.startDate) {
      params.push(filters.startDate);
      sql += ` AND pr.period_start >= $${params.length}`;
    }

    if (filters.endDate) {
      params.push(filters.endDate);
      sql += ` AND pr.period_end <= $${params.length}`;
    }

    sql += PerformanceSql.FIND_ALL_ORDER;

    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const rows = await BaseQuery.queryMany<any>(client, sql, params);
      return rows.map((row) => PerformanceReviewModel.fromRow(row));
    } finally {
      client.release();
    }
  }

  async upsert(payload: {
    userId: string;
    periodStart: string;
    periodEnd: string;
    score: number;
    bonusAmount: number;
    notes?: string | null;
    createdBy?: string | null;
  }): Promise<PerformanceReviewEntity | null> {
    const params = [
      payload.userId,
      payload.periodStart,
      payload.periodEnd,
      payload.score,
      payload.bonusAmount,
      payload.notes ?? null,
      payload.createdBy ?? null,
    ];

    const client = await this.db.getPool().connect();
    try {
      await this.ensureSchema(client);
      const row = await BaseQuery.queryOne<any>(
        client,
        PerformanceSql.UPSERT,
        params,
      );
      if (!row) return null;
      const withUser = await BaseQuery.queryOne<any>(
        client,
        `${PerformanceSql.FIND_ALL_BASE} AND pr.id = $1`,
        [row.id],
      );
      return withUser ? PerformanceReviewModel.fromRow(withUser) : null;
    } finally {
      client.release();
    }
  }
}

