      const result = await service.removeClient('socket-1');

      expect(result).toEqual([
        {
          projectId: 'project-1',
          activeUsers: [],
        },
      ]);
    });

    it('should only remove disconnected user, keep others', async () => {
      await service.addClientToProject(
        'socket-1',
        'user-1',
        'a@b.com',
        'User One',
        '/app/dashboard',
