export interface TaskAssigneeEntity {
  userId: string;
  email: string | null;
  firstName: string | null;
  lastName: string | null;
}

export interface TaskEntity {
  id: string;
  projectId: string;
  title: string;
  description: string | null;
  status: string;
  priority: string;
  assigneeId: string | null;
  assigneeIds: string[];
  assignees: TaskAssigneeEntity[];
  dueDate: string | null;
  createdBy: string;
  createdAt: Date;
  updatedAt: Date;
  // optional joined fields
  assigneeEmail?: string;
  assigneeFirstName?: string;
  assigneeLastName?: string;
}

export const TASK_STATUSES = [
  'TODO',
  'IN_PROGRESS',
  'IN_REVIEW',
  'DONE',
  'BLOCKED',
];
export const TASK_PRIORITIES = ['LOW', 'MEDIUM', 'HIGH', 'URGENT'];

export class Task {
  private static parseAssignees(row: any): TaskAssigneeEntity[] {
    const value = row?.assignees;
    if (!Array.isArray(value)) {
      return [];
    }

    return value
      .map((item) => {
        if (!item || typeof item !== 'object') return null;

        const typed = item as Record<string, unknown>;
        const userId = (typed.user_id || typed.userId) as string | undefined;
        if (!userId) {
          return null;
        }

        return {
          userId,
          email: (typed.email as string | null | undefined) ?? null,
          firstName:
            (typed.first_name as string | null | undefined) ??
            (typed.firstName as string | null | undefined) ??
            null,
          lastName:
            (typed.last_name as string | null | undefined) ??
            (typed.lastName as string | null | undefined) ??
            null,
        };
      })
      .filter((item): item is TaskAssigneeEntity => !!item);
  }

  static fromRow(row: any): TaskEntity {
    const assignees = Task.parseAssignees(row);
    const fallbackAssignee =
      assignees.length === 0 && row.assignee_id
        ? [
            {
              userId: row.assignee_id,
              email: row.assignee_email ?? null,
              firstName: row.assignee_first_name ?? null,
              lastName: row.assignee_last_name ?? null,
            },
          ]
        : assignees;

    return {
      id: row.id,
      projectId: row.project_id,
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId: row.assignee_id,
      assigneeIds: fallbackAssignee.map((assignee) => assignee.userId),
      assignees: fallbackAssignee,
      dueDate: row.due_date,
      createdBy: row.created_by,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
      assigneeEmail: row.assignee_email,
      assigneeFirstName: row.assignee_first_name,
      assigneeLastName: row.assignee_last_name,
    };
  }
}

import { Injectable } from '@nestjs/common';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';
import { Task, TaskEntity } from '../domain/task.entity';
import { TasksSql } from './sql/tasks.sql';

@Injectable()
export class TasksRepository {
  constructor(private readonly dbPool: DatabasePool) {}

  private normalizeAssigneeIds(assigneeIds?: string[]): string[] {
    if (!Array.isArray(assigneeIds)) {
      return [];
    }
    return Array.from(
      new Set(
        assigneeIds.map((id) => id?.trim()).filter((id): id is string => !!id),
      ),
    );
  }

  private async replaceTaskAssignees(
    client: any,
    taskId: string,
    assigneeIds: string[],
  ): Promise<void> {
    await BaseQuery.execute(client, TasksSql.clearAssignees, [taskId]);
    if (assigneeIds.length === 0) {
      return;
    }

    await BaseQuery.execute(client, TasksSql.insertAssignees, [
      taskId,
      assigneeIds,
    ]);
  }

  async findByProject(
    projectId: string,
    filters: {
      status?: string;
      priority?: string;
      assigneeId?: string;
      page?: number;
      limit?: number;
    },
  ): Promise<{ data: TaskEntity[]; total: number }> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const conditions: string[] = ['t.project_id = $1'];
      const params: any[] = [projectId];
      let idx = 2;

      if (filters.status) {
        conditions.push(`t.status = $${idx++}`);
        params.push(filters.status);
      }
      if (filters.priority) {
        conditions.push(`t.priority = $${idx++}`);
        params.push(filters.priority);
      }
      if (filters.assigneeId) {
        conditions.push(
          `(t.assignee_id = $${idx} OR EXISTS (
              SELECT 1
              FROM task_assignees ta
              WHERE ta.task_id = t.id AND ta.user_id = $${idx}
          ))`,
        );
        params.push(filters.assigneeId);
        idx += 1;
      }

      const where = `WHERE ${conditions.join(' AND ')}`;
      const page = filters.page || 1;
      const limit = filters.limit || 50;

      const countResult = await BaseQuery.queryOne<{ count: string }>(
        client,
        `${TasksSql.findByProjectCount} ${where}`,
        params,
      );
      const total = parseInt(countResult?.count || '0', 10);

      const offset = (page - 1) * limit;
      params.push(limit, offset);
      const rows = await BaseQuery.queryMany(
        client,
        `${TasksSql.findByProjectData} ${where}
                 ORDER BY
                    CASE t.priority WHEN 'URGENT' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 END,
                    t.created_at DESC
                 LIMIT $${idx++} OFFSET $${idx++}`,
        params,
      );

      return { data: rows.map((row) => Task.fromRow(row)), total };
    } finally {
      client.release();
    }
  }

  async findById(id: string): Promise<TaskEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(client, TasksSql.findById, [id]);
      return row ? Task.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async create(data: {
    projectId: string;
    title: string;
    description?: string;
    priority?: string;
    assigneeId?: string;
    assigneeIds?: string[];
    dueDate?: string;
    createdBy: string;
  }): Promise<TaskEntity> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const normalizedAssigneeIds = this.normalizeAssigneeIds(
        data.assigneeIds ??
          (data.assigneeId !== undefined && data.assigneeId !== null
            ? [data.assigneeId]
            : []),
      );
      const primaryAssigneeId =
        normalizedAssigneeIds[0] ?? data.assigneeId ?? null;

      await client.query('BEGIN');
      const row = await BaseQuery.queryOne(client, TasksSql.create, [
        data.projectId,
        data.title,
        data.description || null,
        data.priority || 'MEDIUM',
        primaryAssigneeId,
        data.dueDate || null,
        data.createdBy,
      ]);
      await this.replaceTaskAssignees(client, row.id, normalizedAssigneeIds);
      await client.query('COMMIT');
      const created = await this.findById(row.id);
      return created ?? Task.fromRow(row);
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  async update(
    id: string,
    data: Partial<{
      title: string;
      description: string;
      priority: string;
      assigneeId: string;
      assigneeIds: string[];
      dueDate: string;
    }>,
  ): Promise<TaskEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      const sets: string[] = [];
      const params: any[] = [];
      let idx = 1;
      let normalizedAssigneeIds: string[] | undefined = undefined;

      if (data.assigneeIds !== undefined) {
        normalizedAssigneeIds = this.normalizeAssigneeIds(data.assigneeIds);
      } else if (data.assigneeId !== undefined) {
        normalizedAssigneeIds = this.normalizeAssigneeIds(
          data.assigneeId ? [data.assigneeId] : [],
        );
      }

      if (data.title !== undefined) {
        sets.push(`title = $${idx++}`);
        params.push(data.title);
      }
      if (data.description !== undefined) {
        sets.push(`description = $${idx++}`);
        params.push(data.description);
      }
      if (data.priority !== undefined) {
        sets.push(`priority = $${idx++}`);
        params.push(data.priority);
      }
      if (normalizedAssigneeIds !== undefined) {
        sets.push(`assignee_id = $${idx++}`);
        params.push(normalizedAssigneeIds[0] ?? null);
      }
      if (data.dueDate !== undefined) {
        sets.push(`due_date = $${idx++}`);
        params.push(data.dueDate);
      }

      if (sets.length === 0) {
        await client.query('COMMIT');
        return this.findById(id);
      }

      sets.push('updated_at = NOW()');
      params.push(id);

      const row = await BaseQuery.queryOne(
        client,
        `${TasksSql.updateBase} ${sets.join(', ')} WHERE id = $${idx}
                 ${TasksSql.updateReturning}`,
        params,
      );
      if (!row) {
        await client.query('COMMIT');
        return null;
      }

      if (normalizedAssigneeIds !== undefined) {
        await this.replaceTaskAssignees(client, row.id, normalizedAssigneeIds);
      }

      await client.query('COMMIT');
      return this.findById(row.id);
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  async updateStatus(id: string, status: string): Promise<TaskEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(client, TasksSql.updateStatus, [
        status,
        id,
      ]);
      return row ? this.findById(row.id) : null;
    } finally {
      client.release();
    }
  }

  async findBlockers(taskId: string): Promise<TaskEntity[]> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const rows = await BaseQuery.queryMany(client, TasksSql.findBlockers, [
        taskId,
      ]);
      return rows.map((row) => Task.fromRow(row));
    } finally {
      client.release();
    }
  }

  async getStatistics(projectId?: string): Promise<{
    byStatus: Record<string, number>;
    byPriority: Record<string, number>;
  }> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      let where = '';
      const params: any[] = [];

      if (projectId) {
        where = 'WHERE project_id = $1';
        params.push(projectId);
      }

      const statusSql = `${TasksSql.statsByStatus} ${where} GROUP BY status`;
      const prioritySql = `${TasksSql.statsByPriority} ${where} GROUP BY priority`;

      const [statusRows, priorityRows] = await Promise.all([
        BaseQuery.queryMany<any>(client, statusSql, params),
        BaseQuery.queryMany<any>(client, prioritySql, params),
      ]);

      const byStatus: Record<string, number> = {};
      statusRows.forEach(
        (row) => (byStatus[row.status] = parseInt(row.count, 10)),
      );

      const byPriority: Record<string, number> = {};
      priorityRows.forEach(
        (row) => (byPriority[row.priority] = parseInt(row.count, 10)),
      );

      return { byStatus, byPriority };
    } finally {
      client.release();
    }
  }
}

