import { Injectable } from '@nestjs/common';
import { UsersRepository } from '../../infrastructure/users.repository';
import { User } from '../../domain/user.entity';

/**
 * UsersAppService — Application Service katmanı
 *
 * UsersService (orchestration) ile Repository arasında ek bir katman sağlar.
 * Çoklu repository işlemlerinin koordinasyonu ve
 * cross-cutting concern'ler (loglama, audit) burada yapılır.
 *
 * Not: Şu an UsersService zaten bu işlevi görüyor.
 * Bu dosya gelecekte servisin büyümesi halinde refactoring için hazırdır.
 */
@Injectable()
export class UsersAppService {
  constructor(private readonly usersRepo: UsersRepository) {}

  /**
   * Kullanıcı var mı kontrolü (email ile)
   */
  async existsByEmail(email: string): Promise<boolean> {
    const user = await this.usersRepo.findByEmail(email);
    return !!user;
  }

  /**
   * Kullanıcıyı güvenli formatta getir
   */
  async getUserSafe(
    id: string,
  ): Promise<ReturnType<typeof User.toSafeResponse> | null> {
    const user = await this.usersRepo.findById(id);
    return user ? User.toSafeResponse(user) : null;
  }

  /**
   * Kullanıcının aktif olup olmadığını kontrol et
   */
  async isUserActive(id: string): Promise<boolean> {
    const user = await this.usersRepo.findById(id);
    return user ? user.isActive : false;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { UsersRepository } from '../../infrastructure/users.repository';
import { PasswordService } from '../../../auth/application/password.service';
import { UpdateUserDto } from '../../api/dto/update-user.dto';
import { User } from '../../domain/user.entity';
import {
  UserNotFoundException,
  UserAlreadyExistsException,
  CannotChangeOwnRoleException,
} from '../../domain/user.errors';

@Injectable()
export class UpdateUserUseCase {
  private readonly logger = new Logger(UpdateUserUseCase.name);

  constructor(
    private readonly usersRepo: UsersRepository,
    private readonly passwordService: PasswordService,
  ) {}

  async execute(
    id: string,
    dto: UpdateUserDto,
    currentUserId: string,
  ): Promise<User> {
    // 1. Check if user exists
    const user = await this.usersRepo.findById(id);
    if (!user) throw new UserNotFoundException();

    // 2. Self-update rule: cannot change own role
    if (
      id === currentUserId &&
      dto.role &&
      String(dto.role) !== String(user.role)
    ) {
      throw new CannotChangeOwnRoleException();
    }

    // 3. Check email uniqueness if email is being changed
    if (dto.email && dto.email !== user.email) {
      const existing = await this.usersRepo.findByEmail(dto.email);
      if (existing) throw new UserAlreadyExistsException();
    }

    // 4. Handle password update separately
    if (dto.password) {
      const passwordHash = await this.passwordService.hash(dto.password);
      await this.usersRepo.updatePassword(id, passwordHash);
    }

    // 5. Transform keys and update
    // Repository expects camelCase matching the interface?
    // UsersRepository.update takes Partial<{ email, firstName, ... }>
    const updateData: any = {};
    if (dto.email) updateData.email = dto.email;
    if (dto.firstName) updateData.firstName = dto.firstName;
    if (dto.lastName) updateData.lastName = dto.lastName;
    if (dto.role) updateData.role = dto.role;
    if (dto.department) updateData.department = dto.department;
    if (dto.subDepartmentId !== undefined) {
      updateData.subDepartmentId = dto.subDepartmentId || null;
    }
    if (dto.phone !== undefined) updateData.phone = dto.phone;
    if (dto.address !== undefined) updateData.address = dto.address;
    if (dto.avatarUrl !== undefined) updateData.avatarUrl = dto.avatarUrl;
    if (dto.avatarFit !== undefined) updateData.avatarFit = dto.avatarFit;
    if (dto.avatarPosition !== undefined) {
      updateData.avatarPosition = dto.avatarPosition;
    }

    const updated = await this.usersRepo.update(id, updateData);

    this.logger.log(`User updated: ${id}`);

    return updated instanceof User ? updated : User.fromRow(updated);
  }
}

import { Role } from '../../../shared/enums/role.enum';

export interface UserEntity {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  role: string;
  department: string | null;
  subDepartmentId: string | null;
  subDepartmentName: string | null;
  phone: string | null;
  address: string | null;
  avatarUrl: string | null;
  avatarFit: string | null;
  avatarPosition: string | null;
  isActive: boolean;
  forcePasswordChange: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export interface UserWithPassword extends UserEntity {
  passwordHash: string;
}

export class User implements UserEntity {
  constructor(
    public id: string,
    public email: string,
    public firstName: string,
    public lastName: string,
    public role: string,
    public department: string | null,
    public subDepartmentId: string | null,
    public subDepartmentName: string | null,
    public phone: string | null,
    public address: string | null,
    public avatarUrl: string | null,
    public avatarFit: string | null,
    public avatarPosition: string | null,
    public isActive: boolean,
    public forcePasswordChange: boolean,
    public createdAt: Date,
    public updatedAt: Date,
  ) {}

  static fromRow(row: any): User {
    return new User(
      row.id,
      row.email,
      row.first_name,
      row.last_name,
      row.role,
      row.department,
      row.sub_department_id ?? null,
      row.sub_department_name ?? null,
      row.phone ?? null,
      row.address ?? null,
      row.avatar_url ?? null,
      row.avatar_fit ?? null,
      row.avatar_position ?? null,
      row.is_active,
      row.force_password_change,
      row.created_at,
      row.updated_at,
    );
  }

  static toSafeResponse(user: UserEntity) {
    return {
      id: user.id,
      email: user.email,
      firstName: user.firstName,
      lastName: user.lastName,
      role: user.role,
      department: user.department,
      subDepartmentId: user.subDepartmentId,
      subDepartmentName: user.subDepartmentName,
      phone: user.phone,
      address: user.address,
      avatarUrl: user.avatarUrl,
      avatarFit: user.avatarFit,
      avatarPosition: user.avatarPosition,
      isActive: user.isActive,
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
    };
  }

  // Domain Behaviors
  activate() {
    this.isActive = true;
    this.updatedAt = new Date();
  }

  deactivate() {
    this.isActive = false;
    this.updatedAt = new Date();
  }

  changeRole(newRole: Role) {
    this.role = newRole;
    this.updatedAt = new Date();
  }

  changeDepartment(newDept: string) {
    this.department = newDept;
    this.updatedAt = new Date();
  }
}

