import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { IStorageProvider, IUploadResult } from './storage.provider.interface';
import { promises as fsPromises, existsSync, mkdirSync } from 'fs';
import * as path from 'path';
import { v4 as uuidv4 } from 'uuid';

@Injectable()
export class LocalFileProvider implements IStorageProvider, OnModuleInit {
  private readonly logger = new Logger(LocalFileProvider.name);
  private readonly uploadDir: string;

  constructor(private readonly configService: ConfigService) {
    this.uploadDir =
      this.configService.get<string>('storage.local.uploadDir') || './uploads';
  }

  onModuleInit() {
    this.ensureUploadDir();
  }

  private resolveUploadDir(): string {
    return path.isAbsolute(this.uploadDir)
      ? this.uploadDir
      : path.resolve(process.cwd(), this.uploadDir);
  }

  private ensureUploadDir() {
    const fullPath = this.resolveUploadDir();
    this.logger.log(`[DEBUG] Checking upload dir: ${fullPath}`);
    try {
      if (!existsSync(fullPath)) {
        mkdirSync(fullPath, { recursive: true });
        this.logger.log(`Created upload directory: ${fullPath}`);
      }
    } catch (error) {
      this.logger.error(`Failed to create upload directory: ${error.message}`);
      // Don't throw, just log. Tests might fail later but we see why.
    }
  }

  async upload(file: Express.Multer.File): Promise<IUploadResult> {
    // We can double check here asynchronously if needed
    const fullPath = this.resolveUploadDir();

    const ext = path.extname(file.originalname);
    const filename = `${uuidv4()}${ext}`;
    const filePath = path.join(fullPath, filename);

    await fsPromises.writeFile(filePath, file.buffer);

    return {
      key: filename,
      url: `/uploads/${filename}`,
      size: file.size,
      mimeType: file.mimetype,
    };
  }

  async delete(key: string): Promise<void> {
    const filePath = path.join(this.resolveUploadDir(), key);
    try {
      await fsPromises.unlink(filePath);
    } catch (error) {
      this.logger.warn(`Failed to delete file ${key}: ${error.message}`);
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import {
  S3Client,
  PutObjectCommand,
  DeleteObjectCommand,
  GetObjectCommand,
} from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
import { v4 as uuidv4 } from 'uuid';

@Injectable()
export class S3StorageProvider {
  private readonly s3Client: S3Client;
  private readonly bucketName: string;
  private readonly logger = new Logger(S3StorageProvider.name);

  constructor(private readonly configService: ConfigService) {
    this.bucketName =
      this.configService.get<string>('S3_BUCKET_NAME') || 'trivexa-storage';

    // AWS S3 client configuration using environment variables
    this.s3Client = new S3Client({
      region: this.configService.get<string>('S3_REGION') || 'eu-central-1',
      credentials: {
        accessKeyId:
          this.configService.get<string>('S3_ACCESS_KEY') || 'dummy-access-key',
        secretAccessKey:
          this.configService.get<string>('S3_SECRET_KEY') || 'dummy-secret-key',
      },
      // If using MinIO or custom endpoint
      ...(this.configService.get<string>('S3_ENDPOINT') && {
        endpoint: this.configService.get<string>('S3_ENDPOINT'),
        forcePathStyle: true,
      }),
    });
  }

  /**
   * Uploads a file buffer to S3
   * @param buffer The file buffer to upload
   * @param mimetype The MIME type of the file
   * @param originalName The original file name
   * @param folder The target folder path in the bucket
   * @returns The generated key and the public/signed URL of the uploaded file
   */
  async uploadFile(
    buffer: Buffer,
    mimetype: string,
    originalName: string,
    folder: string = 'general',
  ): Promise<{ key: string; url: string }> {
    const extension = originalName.split('.').pop();
    const uniqueFileName = `${folder}/${uuidv4()}-${Date.now()}.${extension}`;

    const command = new PutObjectCommand({
      Bucket: this.bucketName,
      Key: uniqueFileName,
      Body: buffer,
      ContentType: mimetype,
      // Optional: ACL: 'public-read' (Configure carefully depending on S3 Bucket Policy)
    });

    try {
      await this.s3Client.send(command);
      this.logger.log(`File uploaded successfully: ${uniqueFileName}`);

      // If the bucket is not public, return a signed URL. Otherwise, return a direct URL.
      // For this example, we'll return a raw S3 path-like URL. A specific CloudFront or public S3 URL is typical here.
      const url = `https://${this.bucketName}.s3.${this.configService.get<string>('S3_REGION') || 'eu-central-1'}.amazonaws.com/${uniqueFileName}`;

      return { key: uniqueFileName, url };
    } catch (error) {
      this.logger.error(`Error uploading file ${originalName} to S3`, error);
      throw new Error(`Failed to upload file to S3: ${error.message}`);
    }
  }

  /**
   * Deletes a file from S3
   * @param key The key/path of the file in the bucket
   */
  async deleteFile(key: string): Promise<void> {
    const command = new DeleteObjectCommand({
      Bucket: this.bucketName,
      Key: key,
    });

    try {
      await this.s3Client.send(command);
      this.logger.log(`File deleted successfully: ${key}`);
    } catch (error) {
      this.logger.error(`Error deleting file ${key} from S3`, error);
      throw new Error(`Failed to delete file from S3: ${error.message}`);
    }
  }

  /**
   * Generates a pre-signed URL for downloading a private file
   * @param key The key/path of the file in the bucket
   * @param expiresIn Expiration time in seconds (default 1 hour)
   */
  async getSignedDownloadUrl(
    key: string,
    expiresIn: number = 3600,
  ): Promise<string> {
    const command = new GetObjectCommand({
      Bucket: this.bucketName,
      Key: key,
    });

    try {
      return await getSignedUrl(this.s3Client, command, { expiresIn });
    } catch (error) {
      this.logger.error(`Error generating signed URL for ${key}`, error);
      throw new Error(`Failed to generate signed URL: ${error.message}`);
    }
  }
}

